export default JSON.parse("{\"workId\":\"han-fei-zi\",\"chapter\":{\"id\":\"han-fei-zi_ch-34\",\"workId\":\"han-fei-zi\",\"order\":34,\"title\":\"外儲說右上\",\"difficulty\":4,\"estimatedMinutes\":24,\"passageIds\":[\"han-fei-zi_ch-34_p-1\",\"han-fei-zi_ch-34_p-2\",\"han-fei-zi_ch-34_p-3\",\"han-fei-zi_ch-34_p-4\",\"han-fei-zi_ch-34_p-5\",\"han-fei-zi_ch-34_p-6\",\"han-fei-zi_ch-34_p-7\",\"han-fei-zi_ch-34_p-8\",\"han-fei-zi_ch-34_p-9\",\"han-fei-zi_ch-34_p-10\",\"han-fei-zi_ch-34_p-11\",\"han-fei-zi_ch-34_p-12\",\"han-fei-zi_ch-34_p-13\",\"han-fei-zi_ch-34_p-14\",\"han-fei-zi_ch-34_p-15\",\"han-fei-zi_ch-34_p-16\",\"han-fei-zi_ch-34_p-17\",\"han-fei-zi_ch-34_p-18\",\"han-fei-zi_ch-34_p-19\",\"han-fei-zi_ch-34_p-20\",\"han-fei-zi_ch-34_p-21\",\"han-fei-zi_ch-34_p-22\",\"han-fei-zi_ch-34_p-23\",\"han-fei-zi_ch-34_p-24\",\"han-fei-zi_ch-34_p-25\",\"han-fei-zi_ch-34_p-26\",\"han-fei-zi_ch-34_p-27\",\"han-fei-zi_ch-34_p-28\",\"han-fei-zi_ch-34_p-29\",\"han-fei-zi_ch-34_p-30\",\"han-fei-zi_ch-34_p-31\",\"han-fei-zi_ch-34_p-32\",\"han-fei-zi_ch-34_p-33\",\"han-fei-zi_ch-34_p-34\",\"han-fei-zi_ch-34_p-35\",\"han-fei-zi_ch-34_p-36\",\"han-fei-zi_ch-34_p-37\",\"han-fei-zi_ch-34_p-38\",\"han-fei-zi_ch-34_p-39\",\"han-fei-zi_ch-34_p-40\",\"han-fei-zi_ch-34_p-41\",\"han-fei-zi_ch-34_p-42\",\"han-fei-zi_ch-34_p-43\",\"han-fei-zi_ch-34_p-44\",\"han-fei-zi_ch-34_p-45\"],\"tags\":[\"法家\",\"帝王術\",\"法術勢\"]},\"passages\":[{\"id\":\"han-fei-zi_ch-34_p-1\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":1,\"canonicalText\":\"君所以治臣者有三：\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-1_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 1 節）中闡述道：君主統治者所以治臣下僚屬的人或事物有三：。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 1 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「君所以治臣者有三：」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「君所以治臣者有三：」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-2\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":2,\"canonicalText\":\"一、勢不足以化則除之。師曠之對，晏子之說，皆合勢之易也而道行之難，是與獸逐走也，未知除患。患之可除，在子夏之說春秋也。善持勢者蚤絕其姦萌，故季孫讓仲尼以遇勢，而況錯之於君乎？是以太公望殺狂矞，而臧獲不乘驥。嗣公知之，故不駕鹿。薛公知之，故與二欒博。此皆知同異之反也。故明主之牧臣也，說在畜烏。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-2_s-1\",\"han-fei-zi_ch-34_p-2_s-2\",\"han-fei-zi_ch-34_p-2_s-3\",\"han-fei-zi_ch-34_p-2_s-4\",\"han-fei-zi_ch-34_p-2_s-5\",\"han-fei-zi_ch-34_p-2_s-6\",\"han-fei-zi_ch-34_p-2_s-7\",\"han-fei-zi_ch-34_p-2_s-8\",\"han-fei-zi_ch-34_p-2_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 2 節）中闡述道：一、至高權力威勢不足以化則除的。師曠的對，晏子的說，皆合至高權力威勢的易啊而且道行的難，是與獸逐走啊，未知除患。患的可除，在子夏的說春秋啊。善持至高權力威勢的人或事物蚤絕他的姦萌，所以季孫讓仲尼以遇至高權力威勢，而且況錯的於君主統治者乎？是以太公望殺狂矞，而且臧獲不乘驥。嗣公知的，所以不駕鹿。薛公知的，所以與二欒博。此皆知同異的反啊。所以明主的牧臣下僚屬啊，說在畜烏。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 2 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一、勢不足以化則除之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一、勢不足以化則除之。師曠之對，晏子之說，皆合勢之易……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-3\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":3,\"canonicalText\":\"二、人主者，利害之軺轂也，射者眾，故人主共矣。是以好惡見則下有因，而人主惑矣；辭言通則臣難言，而主不神矣。說在申子之言六慎，與唐易之言弋也。患在國羊之請變，與宣王之太息也。明之以靖郭氏之獻十珥也，與犀首、甘茂之道穴聞也。堂谿公知術，故問玉卮。昭侯能術，故以聽獨寢。明主之道，在申子之勸獨斷也。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-3_s-1\",\"han-fei-zi_ch-34_p-3_s-2\",\"han-fei-zi_ch-34_p-3_s-3\",\"han-fei-zi_ch-34_p-3_s-4\",\"han-fei-zi_ch-34_p-3_s-5\",\"han-fei-zi_ch-34_p-3_s-6\",\"han-fei-zi_ch-34_p-3_s-7\",\"han-fei-zi_ch-34_p-3_s-8\",\"han-fei-zi_ch-34_p-3_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 3 節）中闡述道：二、人主的人或事物，利害的軺轂啊，射的人或事物眾，所以人主共矣。是以好惡見則下有因，而且人主惑矣；辭言通則臣下僚屬難言，而且主不神矣。說在申子的言六慎，與唐易的言弋啊。患在國羊的請變，與宣王的太息啊。明的以靖郭氏的獻十珥啊，與犀首、甘茂的道穴聞啊。堂谿公知御臣心術權謀，所以問玉卮。昭侯能御臣心術權謀，所以以聽獨寢。明主的道，在申子的勸獨斷啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 3 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「二、人主者，利害之軺轂也，射者眾，故人主共矣」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「二、人主者，利害之軺轂也，射者眾，故人主共矣。是以好……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-4\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":4,\"canonicalText\":\"三、術之不行，有故。不殺其狗則酒酸。夫國亦有狗，且左右皆社鼠也。人主無堯之再誅，與莊王之應太子，而皆有薄媼之決蔡嫗也。知貴不能以教歌之法先揆之，吳起之出愛妻，文公之斬顛頡，皆違其情者也。故能使人彈疽者，必其忍痛者也。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-4_s-1\",\"han-fei-zi_ch-34_p-4_s-2\",\"han-fei-zi_ch-34_p-4_s-3\",\"han-fei-zi_ch-34_p-4_s-4\",\"han-fei-zi_ch-34_p-4_s-5\",\"han-fei-zi_ch-34_p-4_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 4 節）中闡述道：三、御臣心術權謀的不行，有所以。不殺他的狗則酒酸。夫國亦有狗，且左右皆社鼠啊。人主無堯的再誅，與莊王的應太子，而且皆有薄媼的決蔡嫗啊。知貴不能以教歌的國家法度法規先揆的，吳起的出愛妻，文公的斬顛頡，皆違他的情的人或事物啊。所以能使人彈疽的人或事物，必他的忍痛的人或事物啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 4 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「三、術之不行，有故」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「三、術之不行，有故。不殺其狗則酒酸。夫國亦有狗，且左……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-5\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":5,\"canonicalText\":\"右經\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-5_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 5 節）中闡述道：右經。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 5 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「右經」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「右經」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-6\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":6,\"canonicalText\":\"說一\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-6_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 6 節）中闡述道：說一。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 6 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說一」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說一」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-7\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":7,\"canonicalText\":\"賞之譽之不勸，罰之毀之不畏，四者加焉不變，則其除之。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-7_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 7 節）中闡述道：賞賜恩惠的譽的不勸，刑罰制裁的毀的不畏，四的人或事物加焉不變，則他的除的。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 7 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「賞之譽之不勸，罰之毀之不畏，四者加焉不變，則其除之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「賞之譽之不勸，罰之毀之不畏，四者加焉不變，則其除之。」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-8\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":8,\"canonicalText\":\"齊景公之晉，從平公飲，師曠侍坐，始坐，景公問政於師曠曰：「太師將奚以教寡人？」師曠曰：「君必惠民而已。」中坐，酒酣，將出，又復問政於師曠曰：「太師奚以教寡人？」曰：「君必惠民而已矣。」景公出之舍，師曠送之，又問政於師曠，師曠曰：「君必惠民而已矣。」景公歸，思，未醒，而得師曠之所謂。「公子尾、公子夏者，景公之二弟也，甚得齊民，家富貴而民說之，擬於公室，此危吾位者也，今謂我惠民者，使我與二弟爭民邪？」於是反國發廩粟以賦眾貧，散府餘財以賜孤寡，倉無陳粟，府無餘財，宮婦不御者出嫁之，七十受祿米，鬻德惠施於民也，已與二弟爭。居二年，二弟出走，公子夏逃楚，公子尾走晉。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-8_s-1\",\"han-fei-zi_ch-34_p-8_s-2\",\"han-fei-zi_ch-34_p-8_s-3\",\"han-fei-zi_ch-34_p-8_s-4\",\"han-fei-zi_ch-34_p-8_s-5\",\"han-fei-zi_ch-34_p-8_s-6\",\"han-fei-zi_ch-34_p-8_s-7\",\"han-fei-zi_ch-34_p-8_s-8\",\"han-fei-zi_ch-34_p-8_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 8 節）中闡述道：齊景公的晉，從平公飲，師曠侍坐，始坐，景公問政於師曠說道：：太師將奚以教寡人？師曠說道：：君主統治者必惠民而且已。中坐，酒酣，將出，又復問政於師曠說道：：太師奚以教寡人？說道：：君主統治者必惠民而且已矣。景公出的舍，師曠送的，又問政於師曠，師曠說道：：君主統治者必惠民而且已矣。景公歸，思，未醒，而且得師曠的所謂。公子尾、公子夏的人或事物，景公的二弟啊，甚得齊民，家富貴而且民說的，擬於公室，此危吾位的人或事物啊，今謂我惠民的人或事物，使我與二弟爭民邪？於是反國發廩粟以賦眾貧，散府餘財以賜孤寡，倉無陳粟，府無餘財，宮婦不御的人或事物出嫁的，七十受祿米，鬻德惠施於民啊，已與二弟爭。居二年，二弟出走，公子夏逃楚，公子尾走晉。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 8 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「齊景公之晉，從平公飲，師曠侍坐，始坐，景公問政於師曠曰：「太師將奚以教寡人」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「齊景公之晉，從平公飲，師曠侍坐，始坐，景公問政於師曠……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-9\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":9,\"canonicalText\":\"景公與晏子游於少海，登柏寢之臺而還望其國，曰：「美哉，泱泱乎，堂堂乎，後世將孰有此？」晏子對曰：「其田成氏乎？」景公曰：「寡人有此國也，而曰田成氏有之，何也？」晏子對曰：「夫田成氏甚得齊民，其於民也，上之請爵祿行諸大臣，下之私大斗斛區釜以出貸，小鬥斛區釜以收之。殺一牛，取一豆肉，餘以食士。終歲，布帛取二制焉，餘以衣士。故市木之價不加貴於山，澤之魚鹽龜鱉蠃蚌不加貴於海。君重斂，而田成氏厚施。齊嘗大飢，道旁餓死者不可勝數也，父子相牽而趨田成氏者不聞不生。故周秦之民相與歌之曰：謳乎，其己乎苞乎，其往歸田成子乎！《詩》曰：『雖無德與女，式歌且舞。』今田成氏之德，而民之歌舞，民德歸之矣。故曰：其田成氏乎。」公泫然出涕曰：「不亦悲乎！寡人有國而田成氏有之，今為之奈何？」晏子對曰：「君何患焉！若君欲奪之，則近賢而遠不肖，治其煩亂，緩其刑罰，振貧窮而恤孤寡，行恩惠而給不足，民將歸君，則雖有十田成氏，其如君何？」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-9_s-1\",\"han-fei-zi_ch-34_p-9_s-2\",\"han-fei-zi_ch-34_p-9_s-3\",\"han-fei-zi_ch-34_p-9_s-4\",\"han-fei-zi_ch-34_p-9_s-5\",\"han-fei-zi_ch-34_p-9_s-6\",\"han-fei-zi_ch-34_p-9_s-7\",\"han-fei-zi_ch-34_p-9_s-8\",\"han-fei-zi_ch-34_p-9_s-9\",\"han-fei-zi_ch-34_p-9_s-10\",\"han-fei-zi_ch-34_p-9_s-11\",\"han-fei-zi_ch-34_p-9_s-12\",\"han-fei-zi_ch-34_p-9_s-13\",\"han-fei-zi_ch-34_p-9_s-14\",\"han-fei-zi_ch-34_p-9_s-15\",\"han-fei-zi_ch-34_p-9_s-16\",\"han-fei-zi_ch-34_p-9_s-17\",\"han-fei-zi_ch-34_p-9_s-18\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 9 節）中闡述道：景公與晏子游於少海，登柏寢的臺而且還望他的國，說道：：美哉，泱泱乎，堂堂乎，後世將孰有此？晏子對說道：：他的田成氏乎？景公說道：：寡人有此國啊，而且說道：田成氏有的，何啊？晏子對說道：：夫田成氏甚得齊民，他的於民啊，上的請爵祿行諸大臣下僚屬，下的私大斗斛區釜以出貸，小鬥斛區釜以收的。殺一牛，取一豆肉，餘以食士。終歲，布帛取二制焉，餘以衣士。所以市木的價不加貴於山，澤的魚鹽龜鱉蠃蚌不加貴於海。君主統治者重斂，而且田成氏厚施。齊嘗大飢，道旁餓死的人或事物不可勝數啊，父子相牽而且趨田成氏的人或事物不聞不生。所以周秦的民相與歌的說道：：謳乎，他的己乎苞乎，他的往歸田成子乎！《詩》說道：：雖無德與女，式歌且舞。今田成氏的德，而且民的歌舞，民德歸的矣。因此韓絕不是子評論說道：：他的田成氏乎。公泫然出涕說道：：不亦悲乎！寡人有國而且田成氏有的，今為的奈何？晏子對說道：：君主統治者何患焉！若君主統治者欲奪的，則近賢而且遠不肖，治他的煩亂，緩他的刑刑罰制裁，振貧窮而且恤孤寡，行恩惠而且給不足，民將歸君主統治者，則雖有十田成氏，他的如君主統治者何？這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 9 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「景公與晏子游於少海，登柏寢之臺而還望其國，曰：「美哉，泱泱乎，堂堂乎，後世將孰有此」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「景公與晏子游於少海，登柏寢之臺而還望其國，曰：「美哉……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-10\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":10,\"canonicalText\":\"或曰：景公不知用勢，而師曠、晏子不知除患。夫獵者，託車輿之安，用六馬之足，使王良佐轡，則身不勞而易及輕獸矣。今釋車輿之利，捐六馬之足與王良之御，而下走逐獸，則雖樓季之足無時及獸矣，託良馬固車則臧獲有餘。國者、君之車也，勢者、君之馬也。夫不處勢以禁誅擅愛之臣，而必德厚以與天下齊行以爭民，是皆不乘君之車，不因馬之利車而下走者也。故曰：景公不知用勢之主也，而師曠、晏子不知除患之臣也。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-10_s-1\",\"han-fei-zi_ch-34_p-10_s-2\",\"han-fei-zi_ch-34_p-10_s-3\",\"han-fei-zi_ch-34_p-10_s-4\",\"han-fei-zi_ch-34_p-10_s-5\",\"han-fei-zi_ch-34_p-10_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 10 節）中闡述道：或說道：：景公不知用至高權力威勢，而且師曠、晏子不知除患。夫獵的人或事物，託車輿的安，用六馬的足，使王良佐轡，則身不勞而且易及輕獸矣。今釋車輿的利，捐六馬的足與王良的御，而且下走逐獸，則雖樓季的足無時及獸矣，託良馬固車則臧獲有餘。國的人或事物、君主統治者的車啊，至高權力威勢的人或事物、君主統治者的馬啊。夫不處至高權力威勢以禁誅擅愛的臣下僚屬，而且必德厚以與天下齊行以爭民，是皆不乘君主統治者的車，不因馬的利車而且下走的人或事物啊。因此韓絕不是子評論說道：：景公不知用至高權力威勢的主啊，而且師曠、晏子不知除患的臣下僚屬啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 10 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「或曰：景公不知用勢，而師曠、晏子不知除患」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「或曰：景公不知用勢，而師曠、晏子不知除患。夫獵者，託……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-11\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":11,\"canonicalText\":\"子夏曰：「春秋之記臣殺君，子殺父者，以十數矣，皆非一日之積也，有漸而以至矣。」凡姦者，行久而成積，積成而力多，力多而能殺，故明主蚤絕之。今田常之為亂，有漸見矣，而君不誅。晏子不使其君禁侵陵之臣，而使其主行惠，故簡公受其禍。故子夏曰：「善持勢者蚤絕姦之萌。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-11_s-1\",\"han-fei-zi_ch-34_p-11_s-2\",\"han-fei-zi_ch-34_p-11_s-3\",\"han-fei-zi_ch-34_p-11_s-4\",\"han-fei-zi_ch-34_p-11_s-5\",\"han-fei-zi_ch-34_p-11_s-6\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 11 節）中闡述道：子夏說道：：春秋的記臣下僚屬殺君主統治者，子殺父的人或事物，以十數矣，皆絕不是一日的積啊，有漸而且以至矣。凡姦的人或事物，行久而且成積，積成而且力多，力多而且能殺，所以明主蚤絕的。今田常的為亂，有漸見矣，而且君主統治者不誅。晏子不使他的君主統治者禁侵陵的臣下僚屬，而且使他的主行惠，所以簡公受他的禍。所以子夏說道：：善持至高權力威勢的人或事物蚤絕姦的萌。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 11 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「子夏曰：「春秋之記臣殺君，子殺父者，以十數矣，皆非一日之積也，有漸而以至矣」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「子夏曰：「春秋之記臣殺君，子殺父者，以十數矣，皆非一……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-12\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":12,\"canonicalText\":\"季孫相魯，子路為郈令。魯以五月起眾為長溝，當此之為，子路以其私秩粟為漿飯，要作溝者於五父之衢而餐之。孔子聞之，使子貢往覆其飯，擊毀其器，曰：「魯君有民，子奚為乃餐之？」子路怫然怒，攘肱而入請曰：「夫子疾由之為仁義乎？所學於夫子者仁義也，仁義者，與天下共其所有而同其利者也。今以由之秩粟而餐民，不可何也？」孔子曰：「由之野也！吾以女知之，女徒未及也，女故如是之不知禮也！女之餐之，為愛之也。夫禮，天子愛天下，諸侯愛境內，大夫愛官職，士愛其家，過其所愛曰侵。今魯君有民而子擅愛之，是子侵也，不亦誣乎！」言未卒，而季孫使者至，讓曰：「肥也起民而使之，先生使弟子令徒役而餐之，將奪肥之民耶？」孔子駕而去魯。以孔子之賢，而季孫非魯君也，以人臣之資，假人主之術，蚤禁於未形，而子路不得行其私惠，而害不得生，況人主乎？以景公之勢而禁田常之侵也，則必無劫弒之患矣。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-12_s-1\",\"han-fei-zi_ch-34_p-12_s-2\",\"han-fei-zi_ch-34_p-12_s-3\",\"han-fei-zi_ch-34_p-12_s-4\",\"han-fei-zi_ch-34_p-12_s-5\",\"han-fei-zi_ch-34_p-12_s-6\",\"han-fei-zi_ch-34_p-12_s-7\",\"han-fei-zi_ch-34_p-12_s-8\",\"han-fei-zi_ch-34_p-12_s-9\",\"han-fei-zi_ch-34_p-12_s-10\",\"han-fei-zi_ch-34_p-12_s-11\",\"han-fei-zi_ch-34_p-12_s-12\",\"han-fei-zi_ch-34_p-12_s-13\",\"han-fei-zi_ch-34_p-12_s-14\",\"han-fei-zi_ch-34_p-12_s-15\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 12 節）中闡述道：季孫相魯，子路為郈令。魯以五月起眾為長溝，當此的為，子路以他的私秩粟為漿飯，要作溝的人或事物於五父的衢而且餐的。孔子聞的，使子貢往覆他的飯，擊毀他的器，說道：：魯君主統治者有民，子奚為乃餐的？子路怫然怒，攘肱而且入請說道：：夫子疾由的為仁義乎？所學於夫子的人或事物仁義啊，仁義的人或事物，與天下共他的所有而且同他的利的人或事物啊。今以由的秩粟而且餐民，不可何啊？孔子說道：：由的野啊！吾以女知的，女徒未及啊，女所以如是的不知禮啊！女的餐的，為愛的啊。夫禮，天子愛天下，諸侯愛境內，大夫愛官職，士愛他的家，過他的所愛說道：侵。今魯君主統治者有民而且子擅愛的，是子侵啊，不亦誣乎！言未卒，而且季孫使的人或事物至，讓說道：：肥啊起民而且使的，先生使弟子令徒役而且餐的，將奪肥的民耶？孔子駕而且去魯。以孔子的賢，而且季孫絕不是魯君主統治者啊，以人臣下僚屬的資，假人主的御臣心術權謀，蚤禁於未形，而且子路不得行他的私惠，而且害不得生，況人主乎？以景公的至高權力威勢而且禁田常的侵啊，則必無劫弒的患矣。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 12 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「季孫相魯，子路為郈令」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「季孫相魯，子路為郈令。魯以五月起眾為長溝，當此之為，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-13\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":13,\"canonicalText\":\"太公望東封於齊，齊東海上有居士曰狂矞、華士，昆弟二人者立議曰：「吾不臣天子，不友諸侯，耕作而食之，掘井而飲之，吾無求於人也。無上之名，無君之祿，不事仕而事力。」太公望至於營丘，使吏執殺之以為首誅。周公旦從魯聞之，發急傳而問之曰：「夫二子，賢者也。今日饗國而殺賢者，何也？」太公望曰：「是昆弟二人立議曰：『吾不臣天子，不友諸侯，耕作而食之，掘井而飲之，吾無求於人也，無上之名，無君之祿，不事仕而事力。』彼不臣天子者，是望不得而臣也。不友諸侯者，是望不得而使也。耕作而食之，掘井而飲之，無求於人者，是望不得以賞罰勸禁也。且無上名，雖知、不為望用；不仰君祿，雖賢、不為望功。不仕則不治，不任則不忠。且先王之所以使其臣民者，非爵祿則刑罰也。今四者不足以使之，則望當誰為君乎？不服兵革而顯，不親耕耨而名，又所以教於國也。今有馬於此，如驥之狀者，天下之至良也。然而驅之不前，卻之不止，左之不左，右之不右，則臧獲雖賤，不託其足。臧獲之所願託其足於驥者，以驥之可以追利闢害也。今不為人用，臧獲雖賤，不託其足焉。已自謂以為世之賢士，而不為主用，行極賢而不用於君，此非明主之所臣也，亦驥之不可左右矣，是以誅之。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-13_s-1\",\"han-fei-zi_ch-34_p-13_s-2\",\"han-fei-zi_ch-34_p-13_s-3\",\"han-fei-zi_ch-34_p-13_s-4\",\"han-fei-zi_ch-34_p-13_s-5\",\"han-fei-zi_ch-34_p-13_s-6\",\"han-fei-zi_ch-34_p-13_s-7\",\"han-fei-zi_ch-34_p-13_s-8\",\"han-fei-zi_ch-34_p-13_s-9\",\"han-fei-zi_ch-34_p-13_s-10\",\"han-fei-zi_ch-34_p-13_s-11\",\"han-fei-zi_ch-34_p-13_s-12\",\"han-fei-zi_ch-34_p-13_s-13\",\"han-fei-zi_ch-34_p-13_s-14\",\"han-fei-zi_ch-34_p-13_s-15\",\"han-fei-zi_ch-34_p-13_s-16\",\"han-fei-zi_ch-34_p-13_s-17\",\"han-fei-zi_ch-34_p-13_s-18\",\"han-fei-zi_ch-34_p-13_s-19\",\"han-fei-zi_ch-34_p-13_s-20\",\"han-fei-zi_ch-34_p-13_s-21\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 13 節）中闡述道：太公望東封於齊，齊東海上有居士說道：狂矞、華士，昆弟二人的人或事物立議說道：：吾不臣下僚屬天子，不友諸侯，耕作而且食的，掘井而且飲的，吾無求於人啊。無上的名，無君主統治者的祿，不事仕而且事力。太公望至於營丘，使吏執殺的以為首誅。周公旦從魯聞的，發急傳而且問的說道：：夫二子，賢的人或事物啊。今日饗國而且殺賢的人或事物，何啊？太公望說道：：是昆弟二人立議說道：：吾不臣下僚屬天子，不友諸侯，耕作而且食的，掘井而且飲的，吾無求於人啊，無上的名，無君主統治者的祿，不事仕而且事力。彼不臣下僚屬天子的人或事物，是望不得而且臣下僚屬啊。不友諸侯的人或事物，是望不得而且使啊。耕作而且食的，掘井而且飲的，無求於人的人或事物，是望不得以賞賜恩惠刑罰制裁勸禁啊。且無上名，雖知、不為望用；不仰君主統治者祿，雖賢、不為望功。不仕則不治，不任則不忠。且先王的所以使他的臣下僚屬民的人或事物，絕不是爵祿則刑刑罰制裁啊。今四的人或事物不足以使的，則望當誰為君主統治者乎？不服兵革而且顯，不親耕耨而且名，又所以教於國啊。今有馬於此，如驥的狀的人或事物，天下的至良啊。然而且驅的不前，卻的不止，左的不左，右的不右，則臧獲雖賤，不託他的足。臧獲的所願託他的足於驥的人或事物，以驥的可以追利闢害啊。今不為人用，臧獲雖賤，不託他的足焉。已自謂以為世的賢士，而且不為主用，行極賢而且不用於君主統治者，此絕不是明主的所臣下僚屬啊，亦驥的不可左右矣，是以誅的。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 13 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「太公望東封於齊，齊東海上有居士曰狂矞、華士，昆弟二人者立議曰：「吾不臣天子，不友諸侯，耕作而食之，掘井而飲之，吾無求於人也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「太公望東封於齊，齊東海上有居士曰狂矞、華士，昆弟二人……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-14\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":14,\"canonicalText\":\"一曰。太公望東封於齊，海上有賢者狂矞，太公望聞之往請焉，三卻馬於門而狂矞不報見也，太公望誅之。當是時也，周公旦在魯，馳往止之，比至，已誅之矣。周公旦曰：「狂矞，天下賢者也，夫子何為誅之？」太公望曰：「狂矞也議不臣天子，不友諸侯，吾恐其亂法易教也，故以為首誅。今有馬於此，形容似驥也，然驅之不往，引之不前，雖臧獲不託足以旋其軫也。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-14_s-1\",\"han-fei-zi_ch-34_p-14_s-2\",\"han-fei-zi_ch-34_p-14_s-3\",\"han-fei-zi_ch-34_p-14_s-4\",\"han-fei-zi_ch-34_p-14_s-5\",\"han-fei-zi_ch-34_p-14_s-6\",\"han-fei-zi_ch-34_p-14_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 14 節）中闡述道：一說道：。太公望東封於齊，海上有賢的人或事物狂矞，太公望聞的往請焉，三卻馬於門而且狂矞不報見啊，太公望誅的。當是時啊，周公旦在魯，馳往止的，比至，已誅的矣。周公旦說道：：狂矞，天下賢的人或事物啊，夫子何為誅的？太公望說道：：狂矞啊議不臣下僚屬天子，不友諸侯，吾恐他的亂國家法度法規易教啊，所以以為首誅。今有馬於此，形容似驥啊，然驅的不往，引的不前，雖臧獲不託足以旋他的軫啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 14 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。太公望東封於齊，海上有賢者狂矞，太公望聞之往請……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-15\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":15,\"canonicalText\":\"如耳說衛嗣公，衛嗣公說而太息。左右曰：「公何為不相也？」公曰：「夫馬似鹿者而題之千金，然而有百金之馬而無一金之鹿者，馬為人用而鹿不為人用也。今如耳，萬乘之相也，外有大國之意，其心不在衛，雖辯智，亦不為寡人用，吾是以不相也。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-15_s-1\",\"han-fei-zi_ch-34_p-15_s-2\",\"han-fei-zi_ch-34_p-15_s-3\",\"han-fei-zi_ch-34_p-15_s-4\",\"han-fei-zi_ch-34_p-15_s-5\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 15 節）中闡述道：如耳說衛嗣公，衛嗣公說而且太息。左右說道：：公何為不相啊？公說道：：夫馬似鹿的人或事物而且題的千金，然而且有百金的馬而且無一金的鹿的人或事物，馬為人用而且鹿不為人用啊。今如耳，萬乘的相啊，外有大國的意，他的心不在衛，雖辯智，亦不為寡人用，吾是以不相啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 15 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「如耳說衛嗣公，衛嗣公說而太息」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「如耳說衛嗣公，衛嗣公說而太息。左右曰：「公何為不相也……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-16\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":16,\"canonicalText\":\"薛公之相魏昭侯也，左右有欒子者曰陽胡、潘，其於王甚重，而不為薛公，薛公患之。於是乃召與之博，予之人百金，令之昆弟博，俄又益之人二百金。方博有閒，謁者言客張季之子在門，公怫然怒，撫兵而授謁者曰：「殺之，吾聞季之不為文也。」立有閒，時季羽在側，曰：「不然。竊聞季為公甚，顧其人陰未聞耳。」乃輟不殺客，而大禮之曰：「曩者聞季之不為文也，故欲殺之。今誠為文也，豈忘季哉！」告廩獻千石之粟，告府獻五百金，告騶私廄獻良馬固車二乘，因令奄將宮人之美妾二十人並遺季也。欒子因相謂曰：「為公者必利，不為公者必害，吾曹何愛不為公？」因私競勸而遂為之。薛公以人臣之勢，假人主之術也，而害不得生，況錯之人主乎？夫馴烏者斷其下翎焉，斷其下翎則必恃人而食，焉得不馴乎？夫明主畜臣亦然，令臣不得不利君之祿，不得無服上之名；夫利君之祿，服上之名，焉得不服？\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-16_s-1\",\"han-fei-zi_ch-34_p-16_s-2\",\"han-fei-zi_ch-34_p-16_s-3\",\"han-fei-zi_ch-34_p-16_s-4\",\"han-fei-zi_ch-34_p-16_s-5\",\"han-fei-zi_ch-34_p-16_s-6\",\"han-fei-zi_ch-34_p-16_s-7\",\"han-fei-zi_ch-34_p-16_s-8\",\"han-fei-zi_ch-34_p-16_s-9\",\"han-fei-zi_ch-34_p-16_s-10\",\"han-fei-zi_ch-34_p-16_s-11\",\"han-fei-zi_ch-34_p-16_s-12\",\"han-fei-zi_ch-34_p-16_s-13\",\"han-fei-zi_ch-34_p-16_s-14\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 16 節）中闡述道：薛公的相魏昭侯啊，左右有欒子的人或事物說道：陽胡、潘，他的於王甚重，而且不為薛公，薛公患的。於是乃召與的博，予的人百金，令的昆弟博，俄又益的人二百金。方博有閒，謁的人或事物言客張季的子在門，公怫然怒，撫兵而且授謁的人或事物說道：：殺的，吾聞季的不為文啊。立有閒，時季羽在側，說道：：不然。竊聞季為公甚，顧他的人陰未聞耳。乃輟不殺客，而且大禮的說道：：曩的人或事物聞季的不為文啊，所以欲殺的。今誠為文啊，豈忘季哉！告廩獻千石的粟，告府獻五百金，告騶私廄獻良馬固車二乘，因令奄將宮人的美妾二十人並遺季啊。欒子因相謂說道：：為公的人或事物必利，不為公的人或事物必害，吾曹何愛不為公？因私競勸而且遂為的。薛公以人臣下僚屬的至高權力威勢，假人主的御臣心術權謀啊，而且害不得生，況錯的人主乎？夫馴烏的人或事物斷他的下翎焉，斷他的下翎則必恃人而且食，焉得不馴乎？夫明主畜臣下僚屬亦然，令臣下僚屬不得不利君主統治者的祿，不得無服上的名；夫利君主統治者的祿，服上的名，焉得不服？這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 16 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「薛公之相魏昭侯也，左右有欒子者曰陽胡、潘，其於王甚重，而不為薛公，薛公患之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「薛公之相魏昭侯也，左右有欒子者曰陽胡、潘，其於王甚重……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-17\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":17,\"canonicalText\":\"說二\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-17_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 17 節）中闡述道：說二。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 17 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說二」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說二」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-18\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":18,\"canonicalText\":\"《申子》曰：「上明見，人備之；其不明見，人惑之。其知見，人惑之；不知見，人匿之。其無欲見，人司之；其有欲見，人餌之。故曰：吾無從知之，惟無為可以規之。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-18_s-1\",\"han-fei-zi_ch-34_p-18_s-2\",\"han-fei-zi_ch-34_p-18_s-3\",\"han-fei-zi_ch-34_p-18_s-4\",\"han-fei-zi_ch-34_p-18_s-5\",\"han-fei-zi_ch-34_p-18_s-6\",\"han-fei-zi_ch-34_p-18_s-7\",\"han-fei-zi_ch-34_p-18_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 18 節）中闡述道：《申子》說道：：上明見，人備的；他的不明見，人惑的。他的知見，人惑的；不知見，人匿的。他的無欲見，人司的；他的有欲見，人餌的。因此韓絕不是子評論說道：：吾無從知的，惟無為可以規的。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 18 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「《申子》曰：「上明見，人備之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「《申子》曰：「上明見，人備之；其不明見，人惑之。其知……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-19\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":19,\"canonicalText\":\"一曰。《申子》曰：「慎而言也，人且知女；慎而行也，人且隨女。而有知見也，人且匿女；而無知見也，人且意女。女有知也，人且臧女；女無知也，人且行女。故曰：惟無為可以規之。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-19_s-1\",\"han-fei-zi_ch-34_p-19_s-2\",\"han-fei-zi_ch-34_p-19_s-3\",\"han-fei-zi_ch-34_p-19_s-4\",\"han-fei-zi_ch-34_p-19_s-5\",\"han-fei-zi_ch-34_p-19_s-6\",\"han-fei-zi_ch-34_p-19_s-7\",\"han-fei-zi_ch-34_p-19_s-8\",\"han-fei-zi_ch-34_p-19_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 19 節）中闡述道：一說道：。《申子》說道：：慎而且言啊，人且知女；慎而且行啊，人且隨女。而且有知見啊，人且匿女；而且無知見啊，人且意女。女有知啊，人且臧女；女無知啊，人且行女。因此韓絕不是子評論說道：：惟無為可以規的。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 19 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。《申子》曰：「慎而言也，人且知女；慎而行也，人……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-20\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":20,\"canonicalText\":\"田子方問唐易鞠曰：「弋者何慎？」對曰：「鳥以數百目視子，子以二目御之，子謹周子廩。」田子方曰：「善。子加之弋，我加之國。」鄭長者聞之曰：「田子方知欲為廩，而未得所以為廩。夫虛無無見者廩也。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-20_s-1\",\"han-fei-zi_ch-34_p-20_s-2\",\"han-fei-zi_ch-34_p-20_s-3\",\"han-fei-zi_ch-34_p-20_s-4\",\"han-fei-zi_ch-34_p-20_s-5\",\"han-fei-zi_ch-34_p-20_s-6\",\"han-fei-zi_ch-34_p-20_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 20 節）中闡述道：田子方問唐易鞠說道：：弋的人或事物何慎？對說道：：鳥以數百目視子，子以二目御的，子謹周子廩。田子方說道：：善。子加的弋，我加的國。鄭長的人或事物聞的說道：：田子方知欲為廩，而且未得所以為廩。夫虛無無見的人或事物廩啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 20 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「田子方問唐易鞠曰：「弋者何慎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「田子方問唐易鞠曰：「弋者何慎？」對曰：「鳥以數百目視……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-21\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":21,\"canonicalText\":\"一曰。齊宣王問弋於唐易子曰：「弋者奚貴？」唐易子曰：「在於謹廩。」王曰：「何謂謹廩？」對曰：「鳥以數十目視人，人以二目視鳥，奈何不謹廩也？故曰在於謹廩也。」王曰：「然則為天下何以為此廩？今人主以二目視一國，一國以萬目視人主，將何以自為廩乎？」對曰：「鄭長者有言曰：『夫虛靜無為而無見也。』其可以為此廩乎。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-21_s-1\",\"han-fei-zi_ch-34_p-21_s-2\",\"han-fei-zi_ch-34_p-21_s-3\",\"han-fei-zi_ch-34_p-21_s-4\",\"han-fei-zi_ch-34_p-21_s-5\",\"han-fei-zi_ch-34_p-21_s-6\",\"han-fei-zi_ch-34_p-21_s-7\",\"han-fei-zi_ch-34_p-21_s-8\",\"han-fei-zi_ch-34_p-21_s-9\",\"han-fei-zi_ch-34_p-21_s-10\",\"han-fei-zi_ch-34_p-21_s-11\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 21 節）中闡述道：一說道：。齊宣王問弋於唐易子說道：：弋的人或事物奚貴？唐易子說道：：在於謹廩。王說道：：何謂謹廩？對說道：：鳥以數十目視人，人以二目視鳥，奈何不謹廩啊？因此韓絕不是子評論說道：在於謹廩啊。王說道：：然則為天下何以為此廩？今人主以二目視一國，一國以萬目視人主，將何以自為廩乎？對說道：：鄭長的人或事物有言說道：：夫虛靜無為而且無見啊。他的可以為此廩乎。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 21 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。齊宣王問弋於唐易子曰：「弋者奚貴？」唐易子曰：……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-22\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":22,\"canonicalText\":\"國羊重於鄭君，聞君之惡己也，侍飲，因先謂君曰：「臣適不幸而有過，願君幸而告之，臣請變更，則臣免死罪矣。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-22_s-1\",\"han-fei-zi_ch-34_p-22_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 22 節）中闡述道：國羊重於鄭君主統治者，聞君主統治者的惡己啊，侍飲，因先謂君主統治者說道：：臣下僚屬適不幸而且有過，願君主統治者幸而且告的，臣下僚屬請變更，則臣下僚屬免死罪矣。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 22 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「國羊重於鄭君，聞君之惡己也，侍飲，因先謂君曰：「臣適不幸而有過，願君幸而告之，臣請變更，則臣免死罪矣」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「國羊重於鄭君，聞君之惡己也，侍飲，因先謂君曰：「臣適……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-23\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":23,\"canonicalText\":\"客有說韓宣王，宣王說而太息，左右引王之說之以先告客以為德。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-23_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 23 節）中闡述道：客有說韓宣王，宣王說而且太息，左右引王的說的以先告客以為德。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 23 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「客有說韓宣王，宣王說而太息，左右引王之說之以先告客以為德」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「客有說韓宣王，宣王說而太息，左右引王之說之以先告客以……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-24\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":24,\"canonicalText\":\"靖郭君之相齊也，王后死，未知所置，乃獻玉珥以知之。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-24_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 24 節）中闡述道：靖郭君主統治者的相齊啊，王后死，未知所置，乃獻玉珥以知的。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 24 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「靖郭君之相齊也，王后死，未知所置，乃獻玉珥以知之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「靖郭君之相齊也，王后死，未知所置，乃獻玉珥以知之。」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-25\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":25,\"canonicalText\":\"一曰。薛公相齊，齊威王夫人死，中有十孺子皆貴於王，薛公欲知王所欲立而請置一人以為夫人，王聽之、則是說行於王而重於置夫人也，王不聽、是說不行而輕於置夫人也，欲先知王之所欲置以勸王置之，於是為十玉珥而美其一而獻之，王以賦十孺子，明日坐，視美珥之所在而勸王以為夫人。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-25_s-1\",\"han-fei-zi_ch-34_p-25_s-2\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 25 節）中闡述道：一說道：。薛公相齊，齊威王夫人死，中有十孺子皆貴於王，薛公欲知王所欲立而且請置一人以為夫人，王聽的、則是說行於王而且重於置夫人啊，王不聽、是說不行而且輕於置夫人啊，欲先知王的所欲置以勸王置的，於是為十玉珥而且美他的一而且獻的，王以賦十孺子，明日坐，視美珥的所在而且勸王以為夫人。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 25 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。薛公相齊，齊威王夫人死，中有十孺子皆貴於王，薛……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-26\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":26,\"canonicalText\":\"甘茂相秦惠王，惠王愛公孫衍，與之閒有所言，曰：「寡人將相子。」甘茂之吏道穴聞之，以告甘茂，甘茂入見王，曰：「王得賢相，臣敢再拜賀。」王曰：「寡人託國於子，安更得賢相？」對曰：「將相犀首。」王曰：「子安聞之？」對曰：「犀首告臣。」王怒犀首之泄，乃逐之。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-26_s-1\",\"han-fei-zi_ch-34_p-26_s-2\",\"han-fei-zi_ch-34_p-26_s-3\",\"han-fei-zi_ch-34_p-26_s-4\",\"han-fei-zi_ch-34_p-26_s-5\",\"han-fei-zi_ch-34_p-26_s-6\",\"han-fei-zi_ch-34_p-26_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 26 節）中闡述道：甘茂相秦惠王，惠王愛公孫衍，與的閒有所言，說道：：寡人將相子。甘茂的吏道穴聞的，以告甘茂，甘茂入見王，說道：：王得賢相，臣下僚屬敢再拜賀。王說道：：寡人託國於子，安更得賢相？對說道：：將相犀首。王說道：：子安聞的？對說道：：犀首告臣下僚屬。王怒犀首的泄，乃逐的。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 26 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「甘茂相秦惠王，惠王愛公孫衍，與之閒有所言，曰：「寡人將相子」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「甘茂相秦惠王，惠王愛公孫衍，與之閒有所言，曰：「寡人……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-27\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":27,\"canonicalText\":\"一曰。犀首，天下之善將也，梁王之臣也。秦王欲得之與治天下，犀首曰：「衍其人臣者也，不敢離主之國。」居期年，犀首抵罪於梁王，逃而入秦，秦王甚善之。樗裏疾，秦之將也，恐犀首之代之將也，鑿穴於王之所常隱語者，俄而王果與犀首計曰：「吾欲攻韓，奚如？」犀首曰：「秋可矣。」王曰：「吾欲以國累子，子必勿泄也。」犀首反走再拜曰：「受命。」於是樗裏疾也道穴聽之，矣郎中皆曰：「兵秋起攻韓犀首為將。」於是日也郎中盡知之，於是月也境內盡知之。王召樗裏疾曰：「是何匈匈也，何道出？」樗裏疾曰：「似犀首也。」王曰：「吾無與犀首言也，其犀首何哉？」樗裏疾曰：「犀首也羈旅，新抵罪，其心孤，是言自嫁於眾。」王曰：「然。」使人召犀首，已逃諸侯矣。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-27_s-1\",\"han-fei-zi_ch-34_p-27_s-2\",\"han-fei-zi_ch-34_p-27_s-3\",\"han-fei-zi_ch-34_p-27_s-4\",\"han-fei-zi_ch-34_p-27_s-5\",\"han-fei-zi_ch-34_p-27_s-6\",\"han-fei-zi_ch-34_p-27_s-7\",\"han-fei-zi_ch-34_p-27_s-8\",\"han-fei-zi_ch-34_p-27_s-9\",\"han-fei-zi_ch-34_p-27_s-10\",\"han-fei-zi_ch-34_p-27_s-11\",\"han-fei-zi_ch-34_p-27_s-12\",\"han-fei-zi_ch-34_p-27_s-13\",\"han-fei-zi_ch-34_p-27_s-14\",\"han-fei-zi_ch-34_p-27_s-15\",\"han-fei-zi_ch-34_p-27_s-16\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 27 節）中闡述道：一說道：。犀首，天下的善將啊，梁王的臣下僚屬啊。秦王欲得的與治天下，犀首說道：：衍他的人臣下僚屬的人或事物啊，不敢離主的國。居期年，犀首抵罪於梁王，逃而且入秦，秦王甚善的。樗裏疾，秦的將啊，恐犀首的代的將啊，鑿穴於王的所常隱語的人或事物，俄而且王果與犀首計說道：：吾欲攻韓，奚如？犀首說道：：秋可矣。王說道：：吾欲以國累子，子必勿泄啊。犀首反走再拜說道：：受命。於是樗裏疾啊道穴聽的，矣郎中皆說道：：兵秋起攻韓犀首為將。於是日啊郎中盡知的，於是月啊境內盡知的。王召樗裏疾說道：：是何匈匈啊，何道出？樗裏疾說道：：似犀首啊。王說道：：吾無與犀首言啊，他的犀首何哉？樗裏疾說道：：犀首啊羈旅，新抵罪，他的心孤，是言自嫁於眾。王說道：：然。使人召犀首，已逃諸侯矣。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 27 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。犀首，天下之善將也，梁王之臣也。秦王欲得之與治……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-28\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":28,\"canonicalText\":\"堂谿公謂昭侯曰：「今有千金之玉卮，通而無當，可以盛水乎？」昭侯曰：「不可。」「有瓦器而不漏，可以盛酒乎？」昭侯曰：「可。」對曰：「夫瓦器至賤也，不漏，可以盛酒。雖有乎千金之玉卮，至貴，而無當，漏，不可盛水，則人孰注漿哉？今為人主而漏其群臣之語，是猶無當之玉卮也，雖有聖智，莫盡其術，為其漏也。」昭侯曰：「然。」昭侯聞堂谿公之言，自此之後，欲發天下之大事，未嘗不獨寢，恐夢言而使人知其謀也。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-28_s-1\",\"han-fei-zi_ch-34_p-28_s-2\",\"han-fei-zi_ch-34_p-28_s-3\",\"han-fei-zi_ch-34_p-28_s-4\",\"han-fei-zi_ch-34_p-28_s-5\",\"han-fei-zi_ch-34_p-28_s-6\",\"han-fei-zi_ch-34_p-28_s-7\",\"han-fei-zi_ch-34_p-28_s-8\",\"han-fei-zi_ch-34_p-28_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 28 節）中闡述道：堂谿公謂昭侯說道：：今有千金的玉卮，通而且無當，可以盛水乎？昭侯說道：：不可。有瓦器而且不漏，可以盛酒乎？昭侯說道：：可。對說道：：夫瓦器至賤啊，不漏，可以盛酒。雖有乎千金的玉卮，至貴，而且無當，漏，不可盛水，則人孰注漿哉？今為人主而且漏他的群臣下僚屬的語，是猶無當的玉卮啊，雖有聖智，莫盡他的御臣心術權謀，為他的漏啊。昭侯說道：：然。昭侯聞堂谿公的言，自此的後，欲發天下的大事，未嘗不獨寢，恐夢言而且使人知他的謀啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 28 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「堂谿公謂昭侯曰：「今有千金之玉卮，通而無當，可以盛水乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「堂谿公謂昭侯曰：「今有千金之玉卮，通而無當，可以盛水……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-29\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":29,\"canonicalText\":\"一曰。堂谿公見昭侯曰：「今有白玉之卮而無當，有瓦卮而有當，君渴，將何以飲？」君曰：「以瓦卮。」堂谿公曰：「白玉之卮美，而君不以飲者，以其無當耶？」君曰：「然。」堂谿公曰：「為人主而漏泄其群臣之語，譬猶玉卮之無當。」堂谿公每見而出，昭侯必獨臥，惟恐夢言泄於妻妾。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-29_s-1\",\"han-fei-zi_ch-34_p-29_s-2\",\"han-fei-zi_ch-34_p-29_s-3\",\"han-fei-zi_ch-34_p-29_s-4\",\"han-fei-zi_ch-34_p-29_s-5\",\"han-fei-zi_ch-34_p-29_s-6\",\"han-fei-zi_ch-34_p-29_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 29 節）中闡述道：一說道：。堂谿公見昭侯說道：：今有白玉的卮而且無當，有瓦卮而且有當，君主統治者渴，將何以飲？君主統治者說道：：以瓦卮。堂谿公說道：：白玉的卮美，而且君主統治者不以飲的人或事物，以他的無當耶？君主統治者說道：：然。堂谿公說道：：為人主而且漏泄他的群臣下僚屬的語，譬猶玉卮的無當。堂谿公每見而且出，昭侯必獨臥，惟恐夢言泄於妻妾。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 29 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。堂谿公見昭侯曰：「今有白玉之卮而無當，有瓦卮而……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-30\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":30,\"canonicalText\":\"《申子》曰：「獨視者謂明，獨聽者謂聰。能獨斷者，故可以為天下主。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-30_s-1\",\"han-fei-zi_ch-34_p-30_s-2\",\"han-fei-zi_ch-34_p-30_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 30 節）中闡述道：《申子》說道：：獨視的人或事物謂明，獨聽的人或事物謂聰。能獨斷的人或事物，所以可以為天下主。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 30 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「《申子》曰：「獨視者謂明，獨聽者謂聰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「《申子》曰：「獨視者謂明，獨聽者謂聰。能獨斷者，故可……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-31\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":31,\"canonicalText\":\"說三\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-31_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 31 節）中闡述道：說三。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 31 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「說三」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「說三」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-32\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":32,\"canonicalText\":\"宋人有酤酒者，升概甚平，遇客甚謹，為酒甚美，縣幟甚高，著然不售，酒酸，怪其故，問其所知閭1長者楊倩，倩曰：「汝狗猛耶。」曰：「狗猛則酒何故而不售？」曰：「人畏焉。或令孺子懷錢挈壺罋而往酤，而狗迓而齕之，此酒所以酸而不售也。」夫國亦有狗，有道之士懷其術而欲以明萬乘之主，大臣為猛狗迎而齕之，此人主之所以蔽脅，而有道之士所以不用也。故桓公問管仲「治國最奚患？」對曰：「最患社鼠矣。」公曰：「何患社鼠哉？」對曰：「君亦見夫為社者乎？樹木而塗之，鼠穿其間，掘穴託其中，燻之則恐焚木，灌之則恐塗阤，此社鼠之所以不得也。今人君之左右，出則為勢重而收利於民，入則比周而蔽惡於君，內閒主之情以告外，外內為重，諸臣百吏以為富，吏不誅則亂法，誅之則君不安，據而有之，此亦國之社鼠也。」故人臣執柄而擅禁，明為己者必利，而不為己者必害，此亦猛狗也。夫大臣為猛狗而齕有道之士矣，左右又為社鼠而閒主之情，人主不覺，如此，主焉得無壅，國焉得無亡乎？\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-32_s-1\",\"han-fei-zi_ch-34_p-32_s-2\",\"han-fei-zi_ch-34_p-32_s-3\",\"han-fei-zi_ch-34_p-32_s-4\",\"han-fei-zi_ch-34_p-32_s-5\",\"han-fei-zi_ch-34_p-32_s-6\",\"han-fei-zi_ch-34_p-32_s-7\",\"han-fei-zi_ch-34_p-32_s-8\",\"han-fei-zi_ch-34_p-32_s-9\",\"han-fei-zi_ch-34_p-32_s-10\",\"han-fei-zi_ch-34_p-32_s-11\",\"han-fei-zi_ch-34_p-32_s-12\",\"han-fei-zi_ch-34_p-32_s-13\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 32 節）中闡述道：宋人有酤酒的人或事物，升概甚平，遇客甚謹，為酒甚美，縣幟甚高，著然不售，酒酸，怪他的所以，問他的所知閭1長的人或事物楊倩，倩說道：：汝狗猛耶。說道：：狗猛則酒何所以而且不售？說道：：人畏焉。或令孺子懷錢挈壺罋而且往酤，而且狗迓而且齕的，此酒所以酸而且不售啊。夫國亦有狗，有道的士懷他的御臣心術權謀而且欲以明萬乘的主，大臣下僚屬為猛狗迎而且齕的，此人主的所以蔽脅，而且有道的士所以不用啊。所以桓公問管仲治國最奚患？對說道：：最患社鼠矣。公說道：：何患社鼠哉？對說道：：君主統治者亦見夫為社的人或事物乎？樹木而且塗的，鼠穿他的間，掘穴託他的中，燻的則恐焚木，灌的則恐塗阤，此社鼠的所以不得啊。今人君主統治者的左右，出則為至高權力威勢重而且收利於民，入則比周而且蔽惡於君主統治者，內閒主的情以告外，外內為重，諸臣下僚屬百吏以為富，吏不誅則亂國家法度法規，誅的則君主統治者不安，據而且有的，此亦國的社鼠啊。所以人臣下僚屬執柄而且擅禁，明為己的人或事物必利，而且不為己的人或事物必害，此亦猛狗啊。夫大臣下僚屬為猛狗而且齕有道的士矣，左右又為社鼠而且閒主的情，人主不覺，如此，主焉得無壅，國焉得無亡乎？這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 32 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「宋人有酤酒者，升概甚平，遇客甚謹，為酒甚美，縣幟甚高，著然不售，酒酸，怪其故，問其所知閭1長者楊倩，倩曰：「汝狗猛耶」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「宋人有酤酒者，升概甚平，遇客甚謹，為酒甚美，縣幟甚高……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-33\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":33,\"canonicalText\":\"一曰。宋之酤酒者有莊氏者，其酒常美，或使僕往酤莊氏之酒，其狗齕人，使者不敢往，乃酤佗家之酒，問曰：「何為不酤莊氏之酒？」對曰：「今日莊氏之酒酸。」故曰：不殺其狗則酒酸。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-33_s-1\",\"han-fei-zi_ch-34_p-33_s-2\",\"han-fei-zi_ch-34_p-33_s-3\",\"han-fei-zi_ch-34_p-33_s-4\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 33 節）中闡述道：一說道：。宋的酤酒的人或事物有莊氏的人或事物，他的酒常美，或使僕往酤莊氏的酒，他的狗齕人，使的人或事物不敢往，乃酤佗家的酒，問說道：：何為不酤莊氏的酒？對說道：：今日莊氏的酒酸。因此韓絕不是子評論說道：：不殺他的狗則酒酸。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 33 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。宋之酤酒者有莊氏者，其酒常美，或使僕往酤莊氏之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-34\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":34,\"canonicalText\":\"一曰。桓公問管仲曰：「治國何患？」對曰：「最苦社鼠。夫社木而塗之，鼠因自託也。燻之則木焚，灌之則塗阤，此所以苦於社鼠也。今人君左右，出則為勢重以收利於民，入則比周謾侮蔽惡以欺於君，不誅則亂法，誅之則人主危，據而有之，此亦社鼠也。」故人臣執柄擅禁，明為己者必利，不為己者必害，亦猛狗也。故左右為社鼠，用事者為猛狗，則術不行矣。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-34_s-1\",\"han-fei-zi_ch-34_p-34_s-2\",\"han-fei-zi_ch-34_p-34_s-3\",\"han-fei-zi_ch-34_p-34_s-4\",\"han-fei-zi_ch-34_p-34_s-5\",\"han-fei-zi_ch-34_p-34_s-6\",\"han-fei-zi_ch-34_p-34_s-7\",\"han-fei-zi_ch-34_p-34_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 34 節）中闡述道：一說道：。桓公問管仲說道：：治國何患？對說道：：最苦社鼠。夫社木而且塗的，鼠因自託啊。燻的則木焚，灌的則塗阤，此所以苦於社鼠啊。今人君主統治者左右，出則為至高權力威勢重以收利於民，入則比周謾侮蔽惡以欺於君主統治者，不誅則亂國家法度法規，誅的則人主危，據而且有的，此亦社鼠啊。所以人臣下僚屬執柄擅禁，明為己的人或事物必利，不為己的人或事物必害，亦猛狗啊。所以左右為社鼠，用事的人或事物為猛狗，則御臣心術權謀不行矣。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 34 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。桓公問管仲曰：「治國何患？」對曰：「最苦社鼠。……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-35\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":35,\"canonicalText\":\"堯欲傳天下於舜，鯀諫曰：「不祥哉！孰以天下而傳之於匹夫乎？」堯不聽，舉兵而誅，殺鯀於羽山之郊。共工又諫曰：「孰以天下而傳之於匹夫乎？」堯不聽，又舉兵而誅，共工於幽州之都。於是天下莫敢言無傳天下於舜。仲尼聞之曰：「堯之知，舜之賢，非其難者也。夫至乎誅諫者必傳之舜，乃其難也。」一曰。「不以其所疑敗其所察則難也。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-35_s-1\",\"han-fei-zi_ch-34_p-35_s-2\",\"han-fei-zi_ch-34_p-35_s-3\",\"han-fei-zi_ch-34_p-35_s-4\",\"han-fei-zi_ch-34_p-35_s-5\",\"han-fei-zi_ch-34_p-35_s-6\",\"han-fei-zi_ch-34_p-35_s-7\",\"han-fei-zi_ch-34_p-35_s-8\",\"han-fei-zi_ch-34_p-35_s-9\",\"han-fei-zi_ch-34_p-35_s-10\",\"han-fei-zi_ch-34_p-35_s-11\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 35 節）中闡述道：堯欲傳天下於舜，鯀諫說道：：不祥哉！孰以天下而且傳的於匹夫乎？堯不聽，舉兵而且誅，殺鯀於羽山的郊。共工又諫說道：：孰以天下而且傳的於匹夫乎？堯不聽，又舉兵而且誅，共工於幽州的都。於是天下莫敢言無傳天下於舜。仲尼聞的說道：：堯的知，舜的賢，絕不是他的難的人或事物啊。夫至乎誅諫的人或事物必傳的舜，乃他的難啊。一說道：。不以他的所疑敗他的所察則難啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 35 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「堯欲傳天下於舜，鯀諫曰：「不祥哉」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「堯欲傳天下於舜，鯀諫曰：「不祥哉！孰以天下而傳之於匹……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-36\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":36,\"canonicalText\":\"荊莊王有茅門之法曰：「群臣大夫諸公子入朝，馬蹄踐霤者，廷理斬其輈，戮其御。」於是太子入朝，馬蹄踐霤，廷理斬其輈，戮其御。太子怒，入為王泣曰：「為我誅戮廷理。」王曰：「法者所以敬宗廟，尊社稷。故能立法從令尊敬社稷者，社稷之臣也，焉可誅也？夫犯法廢令不尊敬社稷者，是臣乘君而下尚校也。臣乘君則主失威，下尚校則上位危。威失位危，社稷不守，吾將何以遺子孫？」於是太子乃還走，避舍露宿三日，北面再拜請死罪。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-36_s-1\",\"han-fei-zi_ch-34_p-36_s-2\",\"han-fei-zi_ch-34_p-36_s-3\",\"han-fei-zi_ch-34_p-36_s-4\",\"han-fei-zi_ch-34_p-36_s-5\",\"han-fei-zi_ch-34_p-36_s-6\",\"han-fei-zi_ch-34_p-36_s-7\",\"han-fei-zi_ch-34_p-36_s-8\",\"han-fei-zi_ch-34_p-36_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 36 節）中闡述道：荊莊王有茅門的國家法度法規說道：：群臣下僚屬大夫諸公子入朝，馬蹄踐霤的人或事物，廷理斬他的輈，戮他的御。於是太子入朝，馬蹄踐霤，廷理斬他的輈，戮他的御。太子怒，入為王泣說道：：為我誅戮廷理。王說道：：國家法度法規的人或事物所以敬宗廟，尊社稷。所以能立國家法度法規從令尊敬社稷的人或事物，社稷的臣下僚屬啊，焉可誅啊？夫犯國家法度法規廢令不尊敬社稷的人或事物，是臣下僚屬乘君主統治者而且下尚校啊。臣下僚屬乘君主統治者則主失威，下尚校則上位危。威失位危，社稷不守，吾將何以遺子孫？於是太子乃還走，避舍露宿三日，北面再拜請死罪。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 36 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「荊莊王有茅門之法曰：「群臣大夫諸公子入朝，馬蹄踐霤者，廷理斬其輈，戮其御」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「荊莊王有茅門之法曰：「群臣大夫諸公子入朝，馬蹄踐霤者……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-37\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":37,\"canonicalText\":\"一曰。楚王急召太子。楚國之法，車不得至於茆門。天雨，廷中有潦，太子遂驅車至於茆門。廷理曰：「車不得至茆門，非法也。」太子曰：「王召急，不得須無潦。」遂驅之，廷理舉殳而擊其馬，敗其駕。太子入為王泣曰：「廷中多潦，驅車至茆門，廷理曰非法也，舉殳擊臣馬，敗臣駕，王必誅之。」王曰：「前有老主而不踰，後有儲主而不屬，矜矣。是真吾守法之臣也。」乃益爵二級，而開後門出太子。「勿復過。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-37_s-1\",\"han-fei-zi_ch-34_p-37_s-2\",\"han-fei-zi_ch-34_p-37_s-3\",\"han-fei-zi_ch-34_p-37_s-4\",\"han-fei-zi_ch-34_p-37_s-5\",\"han-fei-zi_ch-34_p-37_s-6\",\"han-fei-zi_ch-34_p-37_s-7\",\"han-fei-zi_ch-34_p-37_s-8\",\"han-fei-zi_ch-34_p-37_s-9\",\"han-fei-zi_ch-34_p-37_s-10\",\"han-fei-zi_ch-34_p-37_s-11\",\"han-fei-zi_ch-34_p-37_s-12\",\"han-fei-zi_ch-34_p-37_s-13\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 37 節）中闡述道：一說道：。楚王急召太子。楚國的國家法度法規，車不得至於茆門。天雨，廷中有潦，太子遂驅車至於茆門。廷理說道：：車不得至茆門，絕不是國家法度法規啊。太子說道：：王召急，不得須無潦。遂驅的，廷理舉殳而且擊他的馬，敗他的駕。太子入為王泣說道：：廷中多潦，驅車至茆門，廷理說道：絕不是國家法度法規啊，舉殳擊臣下僚屬馬，敗臣下僚屬駕，王必誅的。王說道：：前有老主而且不踰，後有儲主而且不屬，矜矣。是真吾守國家法度法規的臣下僚屬啊。乃益爵二級，而且開後門出太子。勿復過。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 37 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。楚王急召太子。楚國之法，車不得至於茆門。天雨，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-38\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":38,\"canonicalText\":\"衛嗣君謂薄疑曰：「子小寡人之國以為不足仕，則寡人力能仕子，請進爵以子為上卿。」乃進田萬頃。薄子曰：「疑之母親疑，以疑為能相萬乘所不窕也。然疑家巫有蔡嫗者，疑母甚愛信之，屬之家事焉。疑智足以信言家事，疑母盡以聽疑也。然已與疑言者，亦必復決之於蔡嫗也。故論疑之智能，以疑為能相萬乘而不窕也；論其親，則子母之間也；然猶不免議之於蔡嫗也。今疑之於人主也，非子母之親也，而人主皆有蔡嫗。人主之蔡嫗，必其重人也。重人者，能行私者也。夫行私者，繩之外也；而疑之所言，法之內也。繩之外與法之內，讎也，不相受也。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-38_s-1\",\"han-fei-zi_ch-34_p-38_s-2\",\"han-fei-zi_ch-34_p-38_s-3\",\"han-fei-zi_ch-34_p-38_s-4\",\"han-fei-zi_ch-34_p-38_s-5\",\"han-fei-zi_ch-34_p-38_s-6\",\"han-fei-zi_ch-34_p-38_s-7\",\"han-fei-zi_ch-34_p-38_s-8\",\"han-fei-zi_ch-34_p-38_s-9\",\"han-fei-zi_ch-34_p-38_s-10\",\"han-fei-zi_ch-34_p-38_s-11\",\"han-fei-zi_ch-34_p-38_s-12\",\"han-fei-zi_ch-34_p-38_s-13\",\"han-fei-zi_ch-34_p-38_s-14\",\"han-fei-zi_ch-34_p-38_s-15\",\"han-fei-zi_ch-34_p-38_s-16\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 38 節）中闡述道：衛嗣君主統治者謂薄疑說道：：子小寡人的國以為不足仕，則寡人力能仕子，請進爵以子為上卿。乃進田萬頃。薄子說道：：疑的母親疑，以疑為能相萬乘所不窕啊。然疑家巫有蔡嫗的人或事物，疑母甚愛信的，屬的家事焉。疑智足以信言家事，疑母盡以聽疑啊。然已與疑言的人或事物，亦必復決的於蔡嫗啊。所以論疑的智能，以疑為能相萬乘而且不窕啊；論他的親，則子母的間啊；然猶不免議的於蔡嫗啊。今疑的於人主啊，絕不是子母的親啊，而且人主皆有蔡嫗。人主的蔡嫗，必他的重人啊。重人的人或事物，能行私的人或事物啊。夫行私的人或事物，繩的外啊；而且疑的所言，國家法度法規的內啊。繩的外與國家法度法規的內，讎啊，不相受啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 38 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「衛嗣君謂薄疑曰：「子小寡人之國以為不足仕，則寡人力能仕子，請進爵以子為上卿」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「衛嗣君謂薄疑曰：「子小寡人之國以為不足仕，則寡人力能……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-39\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":39,\"canonicalText\":\"一曰。衛君之晉，謂薄疑曰：「吾欲與子皆行。」薄疑曰：「媼也在中，請歸與媼計之。衛君自請薄媼，薄媼曰：「疑，君之臣也，君有意從之，甚善。」衛君曰：「吾以請之媼，媼許我矣。」薄疑歸言之媼也，曰：「衛君之愛疑奚與媼？」媼曰：「不如吾愛子也。」「衛君之賢疑奚與媼也？」曰：「不如吾賢子也。」「媼與疑計家事，已決矣，乃請決之於卜者蔡嫗。今衛君從疑而行，雖與疑決計，必與他蔡嫗敗之，如是則疑不得長為臣矣。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-39_s-1\",\"han-fei-zi_ch-34_p-39_s-2\",\"han-fei-zi_ch-34_p-39_s-3\",\"han-fei-zi_ch-34_p-39_s-4\",\"han-fei-zi_ch-34_p-39_s-5\",\"han-fei-zi_ch-34_p-39_s-6\",\"han-fei-zi_ch-34_p-39_s-7\",\"han-fei-zi_ch-34_p-39_s-8\",\"han-fei-zi_ch-34_p-39_s-9\",\"han-fei-zi_ch-34_p-39_s-10\",\"han-fei-zi_ch-34_p-39_s-11\",\"han-fei-zi_ch-34_p-39_s-12\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 39 節）中闡述道：一說道：。衛君主統治者的晉，謂薄疑說道：：吾欲與子皆行。薄疑說道：：媼啊在中，請歸與媼計的。衛君主統治者自請薄媼，薄媼說道：：疑，君主統治者的臣下僚屬啊，君主統治者有意從的，甚善。衛君主統治者說道：：吾以請的媼，媼許我矣。薄疑歸言的媼啊，說道：：衛君主統治者的愛疑奚與媼？媼說道：：不如吾愛子啊。衛君主統治者的賢疑奚與媼啊？說道：：不如吾賢子啊。媼與疑計家事，已決矣，乃請決的於卜的人或事物蔡嫗。今衛君主統治者從疑而且行，雖與疑決計，必與他蔡嫗敗的，如是則疑不得長為臣下僚屬矣。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 39 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。衛君之晉，謂薄疑曰：「吾欲與子皆行。」薄疑曰：……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-40\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":40,\"canonicalText\":\"夫教歌者，使先呼而詘之，其聲反清徵者乃教之。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-40_s-1\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 40 節）中闡述道：夫教歌的人或事物，使先呼而且詘的，他的聲反清徵的人或事物乃教的。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 40 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「夫教歌者，使先呼而詘之，其聲反清徵者乃教之」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「夫教歌者，使先呼而詘之，其聲反清徵者乃教之。」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-41\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":41,\"canonicalText\":\"一曰。教歌者，先揆以法，疾呼中宮，徐呼中徵。疾不中宮，徐不中徵，不可謂教。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-41_s-1\",\"han-fei-zi_ch-34_p-41_s-2\",\"han-fei-zi_ch-34_p-41_s-3\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 41 節）中闡述道：一說道：。教歌的人或事物，先揆以國家法度法規，疾呼中宮，徐呼中徵。疾不中宮，徐不中徵，不可謂教。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 41 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。教歌者，先揆以法，疾呼中宮，徐呼中徵。疾不中宮……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-42\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":42,\"canonicalText\":\"吳起，衛左氏中人也。使其妻織組而幅狹於度，吳子使更之，其妻曰：「諾。」及成，復度之，果不中度，吳子大怒。其妻對曰：「吾始經之而不可更也。」吳子出之，其妻請其兄而索入，其兄曰：「吳子，為法者也。其為法也，且欲以與萬乘致功，必先踐之妻妾然後行之，子毋幾索入矣。」其妻之弟又重於衛君，乃因以衛君之重請吳子，吳子不聽，遂去衛而入荊也。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-42_s-1\",\"han-fei-zi_ch-34_p-42_s-2\",\"han-fei-zi_ch-34_p-42_s-3\",\"han-fei-zi_ch-34_p-42_s-4\",\"han-fei-zi_ch-34_p-42_s-5\",\"han-fei-zi_ch-34_p-42_s-6\",\"han-fei-zi_ch-34_p-42_s-7\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 42 節）中闡述道：吳起，衛左氏中人啊。使他的妻織組而且幅狹於度，吳子使更的，他的妻說道：：諾。及成，復度的，果不中度，吳子大怒。他的妻對說道：：吾始經的而且不可更啊。吳子出的，他的妻請他的兄而且索入，他的兄說道：：吳子，為國家法度法規的人或事物啊。他的為國家法度法規啊，且欲以與萬乘致功，必先踐的妻妾然後行的，子毋幾索入矣。他的妻的弟又重於衛君主統治者，乃因以衛君主統治者的重請吳子，吳子不聽，遂去衛而且入荊啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 42 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「吳起，衛左氏中人也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「吳起，衛左氏中人也。使其妻織組而幅狹於度，吳子使更之……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-43\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":43,\"canonicalText\":\"一曰。吳起示其妻以組曰：「子為我織組，令之如是。」組已就而效之，其組異善。起曰：「使子為組，令之如是，而今也異善何也？」其妻曰：「用財若一也，加務善之。」吳起曰：「非語也。」使之衣歸。其父往請之，吳起曰：「起家無虛言。」\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-43_s-1\",\"han-fei-zi_ch-34_p-43_s-2\",\"han-fei-zi_ch-34_p-43_s-3\",\"han-fei-zi_ch-34_p-43_s-4\",\"han-fei-zi_ch-34_p-43_s-5\",\"han-fei-zi_ch-34_p-43_s-6\",\"han-fei-zi_ch-34_p-43_s-7\",\"han-fei-zi_ch-34_p-43_s-8\",\"han-fei-zi_ch-34_p-43_s-9\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 43 節）中闡述道：一說道：。吳起示他的妻以組說道：：子為我織組，令的如是。組已就而且效的，他的組異善。起說道：：使子為組，令的如是，而且今啊異善何啊？他的妻說道：：用財若一啊，加務善的。吳起說道：：絕不是語啊。使的衣歸。他的父往請的，吳起說道：：起家無虛言。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 43 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「一曰」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「一曰。吳起示其妻以組曰：「子為我織組，令之如是。」組……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-44\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":44,\"canonicalText\":\"晉文公問於狐偃曰：「寡人甘肥周於堂，卮酒豆肉集於宮，壺酒不清，生肉不布，殺一牛遍於國中，一歲之功盡以衣士卒，其足以戰民乎？」狐子曰：「不足。」文公曰：「吾弛關市之徵而緩刑罰，其足以戰民乎？」狐子曰：「不足。」文公曰：「吾民之有喪資者，寡人親使郎中視事；有罪者赦之；貧窮不足者與之；其足以戰民乎？」狐子對曰：「不足。此皆所以慎產也。而戰之者，殺之也。民之從公也，為慎產也，公因而迎殺之，失所以為從公矣。」曰：「然則何如足以戰民乎？」狐子對曰：「令無得不戰。」公曰：「無得不戰奈何？」狐子對曰：「信賞必罰，其足以戰。」公曰：「刑罰之極安至？」對曰：「不闢親貴，法行所愛。」文公曰：「善。」明日令田於圃陸，期以日中為期，後期者行軍法焉。於是公有所愛者曰顛頡後期，吏請其罪，文公隕涕而憂。吏曰：「請用事焉。」遂斬顛頡之脊，以徇百姓，以明法之信也。而後百姓皆懼曰：「君於顛頡之貴重如彼甚也，而君猶行法焉，況於我則何有矣？」文公見民之可戰也，於是遂興兵伐原，克之。伐衛，東其畝，取五鹿。攻陽，勝虢，伐曹。南圍鄭，反之陴。罷宋圍，還與荊人戰城濮，大敗荊人，返為踐土之盟，遂成衡雍之義。一舉而八有功。所以然者，無他故異物，從狐偃之謀，假顛頡之脊也。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-44_s-1\",\"han-fei-zi_ch-34_p-44_s-2\",\"han-fei-zi_ch-34_p-44_s-3\",\"han-fei-zi_ch-34_p-44_s-4\",\"han-fei-zi_ch-34_p-44_s-5\",\"han-fei-zi_ch-34_p-44_s-6\",\"han-fei-zi_ch-34_p-44_s-7\",\"han-fei-zi_ch-34_p-44_s-8\",\"han-fei-zi_ch-34_p-44_s-9\",\"han-fei-zi_ch-34_p-44_s-10\",\"han-fei-zi_ch-34_p-44_s-11\",\"han-fei-zi_ch-34_p-44_s-12\",\"han-fei-zi_ch-34_p-44_s-13\",\"han-fei-zi_ch-34_p-44_s-14\",\"han-fei-zi_ch-34_p-44_s-15\",\"han-fei-zi_ch-34_p-44_s-16\",\"han-fei-zi_ch-34_p-44_s-17\",\"han-fei-zi_ch-34_p-44_s-18\",\"han-fei-zi_ch-34_p-44_s-19\",\"han-fei-zi_ch-34_p-44_s-20\",\"han-fei-zi_ch-34_p-44_s-21\",\"han-fei-zi_ch-34_p-44_s-22\",\"han-fei-zi_ch-34_p-44_s-23\",\"han-fei-zi_ch-34_p-44_s-24\",\"han-fei-zi_ch-34_p-44_s-25\",\"han-fei-zi_ch-34_p-44_s-26\",\"han-fei-zi_ch-34_p-44_s-27\",\"han-fei-zi_ch-34_p-44_s-28\",\"han-fei-zi_ch-34_p-44_s-29\",\"han-fei-zi_ch-34_p-44_s-30\",\"han-fei-zi_ch-34_p-44_s-31\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 44 節）中闡述道：晉文公問於狐偃說道：：寡人甘肥周於堂，卮酒豆肉集於宮，壺酒不清，生肉不布，殺一牛遍於國中，一歲的功盡以衣士卒，他的足以戰民乎？狐子說道：：不足。文公說道：：吾弛關市的徵而且緩刑刑罰制裁，他的足以戰民乎？文公說道：：吾民的有喪資的人或事物，寡人親使郎中視事；有罪的人或事物赦的；貧窮不足的人或事物與的；他的足以戰民乎？狐子對說道：：不足。此皆所以慎產啊。而且戰的的人或事物，殺的啊。民的從公啊，為慎產啊，公因而且迎殺的，失所以為從公矣。說道：：然則何如足以戰民乎？狐子對說道：：令無得不戰。公說道：：無得不戰奈何？狐子對說道：：信賞賜恩惠必刑罰制裁，他的足以戰。公說道：：刑刑罰制裁的極安至？對說道：：不闢親貴，國家法度法規行所愛。文公說道：：善。明日令田於圃陸，期以日中為期，後期的人或事物行軍國家法度法規焉。於是公有所愛的人或事物說道：顛頡後期，吏請他的罪，文公隕涕而且憂。吏說道：：請用事焉。遂斬顛頡的脊，以徇百姓，以明國家法度法規的信啊。而且後百姓皆懼說道：：君主統治者於顛頡的貴重如彼甚啊，而且君主統治者猶行國家法度法規焉，況於我則何有矣？文公見民的可戰啊，於是遂興兵伐原，克的。伐衛，東他的畝，取五鹿。攻陽，勝虢，伐曹。南圍鄭，反的陴。罷宋圍，還與荊人戰城濮，大敗荊人，返為踐土的盟，遂成衡雍的義。一舉而且八有功。所以然的人或事物，無他所以異物，從狐偃的謀，假顛頡的脊啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 44 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「晉文公問於狐偃曰：「寡人甘肥周於堂，卮酒豆肉集於宮，壺酒不清，生肉不布，殺一牛遍於國中，一歲之功盡以衣士卒，其足以戰民乎」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「晉文公問於狐偃曰：「寡人甘肥周於堂，卮酒豆肉集於宮，……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}},{\"id\":\"han-fei-zi_ch-34_p-45\",\"chapterId\":\"han-fei-zi_ch-34\",\"order\":45,\"canonicalText\":\"夫痤疽之痛也，非刺骨髓，則煩心不可支也；非如是不能使人以半寸砥石彈之。今人主之於治亦然，非不知有苦則安；欲治其國，非如是不能聽聖知而誅亂臣。亂臣者，必重人。重人者，必人主所甚親愛也。人主所甚親愛也者，是同堅白也。夫以布衣之資，欲以離人主之堅白、所愛，是以解左髀說右髀者，是身必死而說不行者也。\",\"sentenceIds\":[\"han-fei-zi_ch-34_p-45_s-1\",\"han-fei-zi_ch-34_p-45_s-2\",\"han-fei-zi_ch-34_p-45_s-3\",\"han-fei-zi_ch-34_p-45_s-4\",\"han-fei-zi_ch-34_p-45_s-5\",\"han-fei-zi_ch-34_p-45_s-6\",\"han-fei-zi_ch-34_p-45_s-7\",\"han-fei-zi_ch-34_p-45_s-8\"],\"sourceRefs\":[{\"label\":\"《韓非子》—中國哲學書電子化計劃\",\"edition\":\"王先慎《韓非子集解》本\",\"location\":\"https://ctext.org/hanfeizi/zh\",\"accessedAt\":\"2026-08-31\"},{\"label\":\"《韓非子》—維基文庫\",\"edition\":\"四部叢刊景宋本\",\"location\":\"https://zh.wikisource.org/zh-hant/韓非子\",\"accessedAt\":\"2026-08-31\"}],\"readingAid\":{\"translation\":\"【韓非子白話通譯】在《韓非子・外儲說右上》（第 45 節）中闡述道：夫痤疽的痛啊，絕不是刺骨髓，則煩心不可支啊；絕不是如是不能使人以半寸砥石彈的。今人主的於治亦然，絕不是不知有苦則安；欲治他的國，絕不是如是不能聽聖知而且誅亂臣下僚屬。亂臣下僚屬的人或事物，必重人。重人的人或事物，必人主所甚親愛啊。人主所甚親愛啊的人或事物，是同堅白啊。夫以布衣的資，欲以離人主的堅白、所愛，是以解左髀說右髀的人或事物，是身必死而且說不行的人或事物啊。這段法家集大成論述深刻剖析了法術勢結合、富國強兵、賞罰分明、防奸備內與君主治國之權謀大道。\",\"analysis\":\"【法家集大成篇旨與歷史語境】\\\\n本段選自先秦法家集大成之鴻篇鉅著《韓非子》〈外儲說右上〉（第 45 節）。文本依據清王先慎《韓非子集解》與陳奇猷《韓非子集釋》之權威體系，深刻融合了商鞅之「法」、申不害之「術」與慎到之「勢」，為戰國晚期諸侯兼併與大一統專制國家之建立提供了最完備之法家治國理論體系。開篇「夫痤疽之痛也，非刺骨髓，則煩心不可支也」奠定全篇之論述基調。\\\\n\\\\n【寓言政論與冷峻剖析】\\\\n1. 人性論與君權權謀：全段聚焦「夫痤疽之痛也，非刺骨髓，則煩心不可支也；非如是不能使……」，韓非子立足於「人皆自為（趨利避害）」之人性實然，冷靜剖析君臣、上下與列國之間複雜的權力博弈，強調君主必須獨操「賞」、「罰」之二柄，明法審令以御羣下。\\\\n2. 說理藝術與寓言筆法：論辯犀利透徹、邏輯嚴密深沉，善用歷史事例與經典寓言剖析治亂興亡之樞紐，文鋒如霜雪般冷靜嚴峻，具有震撼人心之思想力量。\\\\n\\\\n【制度歷史與哲學評析】\\\\n韓非子總結戰國百家爭鳴之政治實踐，其法治思想與中央集權設計深刻塑造了秦漢以下兩千餘年古代中國之官僚制度與法制傳統，為理解古代政治權力運作與帝王術之最重要經典。\",\"historicalContext\":\"\",\"keywords\":[]}}],\"sentences\":[{\"id\":\"han-fei-zi_ch-34_p-1_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-1\",\"order\":1,\"canonicalText\":\"君所以治臣者有三：\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-2_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-2\",\"order\":1,\"canonicalText\":\"一、勢不足以化則除之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-2_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-2\",\"order\":2,\"canonicalText\":\"師曠之對，晏子之說，皆合勢之易也而道行之難，是與獸逐走也，未知除患。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-2_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-2\",\"order\":3,\"canonicalText\":\"患之可除，在子夏之說春秋也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-2_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-2\",\"order\":4,\"canonicalText\":\"善持勢者蚤絕其姦萌，故季孫讓仲尼以遇勢，而況錯之於君乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-2_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-2\",\"order\":5,\"canonicalText\":\"是以太公望殺狂矞，而臧獲不乘驥。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-2_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-2\",\"order\":6,\"canonicalText\":\"嗣公知之，故不駕鹿。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-2_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-2\",\"order\":7,\"canonicalText\":\"薛公知之，故與二欒博。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-2_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-2\",\"order\":8,\"canonicalText\":\"此皆知同異之反也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-2_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-2\",\"order\":9,\"canonicalText\":\"故明主之牧臣也，說在畜烏。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-3_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-3\",\"order\":1,\"canonicalText\":\"二、人主者，利害之軺轂也，射者眾，故人主共矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-3_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-3\",\"order\":2,\"canonicalText\":\"是以好惡見則下有因，而人主惑矣；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-3_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-3\",\"order\":3,\"canonicalText\":\"辭言通則臣難言，而主不神矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-3_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-3\",\"order\":4,\"canonicalText\":\"說在申子之言六慎，與唐易之言弋也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-3_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-3\",\"order\":5,\"canonicalText\":\"患在國羊之請變，與宣王之太息也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-3_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-3\",\"order\":6,\"canonicalText\":\"明之以靖郭氏之獻十珥也，與犀首、甘茂之道穴聞也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-3_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-3\",\"order\":7,\"canonicalText\":\"堂谿公知術，故問玉卮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-3_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-3\",\"order\":8,\"canonicalText\":\"昭侯能術，故以聽獨寢。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-3_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-3\",\"order\":9,\"canonicalText\":\"明主之道，在申子之勸獨斷也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-4_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-4\",\"order\":1,\"canonicalText\":\"三、術之不行，有故。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-4_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-4\",\"order\":2,\"canonicalText\":\"不殺其狗則酒酸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-4_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-4\",\"order\":3,\"canonicalText\":\"夫國亦有狗，且左右皆社鼠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-4_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-4\",\"order\":4,\"canonicalText\":\"人主無堯之再誅，與莊王之應太子，而皆有薄媼之決蔡嫗也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-4_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-4\",\"order\":5,\"canonicalText\":\"知貴不能以教歌之法先揆之，吳起之出愛妻，文公之斬顛頡，皆違其情者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-4_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-4\",\"order\":6,\"canonicalText\":\"故能使人彈疽者，必其忍痛者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-5_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-5\",\"order\":1,\"canonicalText\":\"右經\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-6_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-6\",\"order\":1,\"canonicalText\":\"說一\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-7_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-7\",\"order\":1,\"canonicalText\":\"賞之譽之不勸，罰之毀之不畏，四者加焉不變，則其除之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-8_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-8\",\"order\":1,\"canonicalText\":\"齊景公之晉，從平公飲，師曠侍坐，始坐，景公問政於師曠曰：「太師將奚以教寡人？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-8_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-8\",\"order\":2,\"canonicalText\":\"」師曠曰：「君必惠民而已。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-8_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-8\",\"order\":3,\"canonicalText\":\"」中坐，酒酣，將出，又復問政於師曠曰：「太師奚以教寡人？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-8_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-8\",\"order\":4,\"canonicalText\":\"」曰：「君必惠民而已矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-8_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-8\",\"order\":5,\"canonicalText\":\"」景公出之舍，師曠送之，又問政於師曠，師曠曰：「君必惠民而已矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-8_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-8\",\"order\":6,\"canonicalText\":\"」景公歸，思，未醒，而得師曠之所謂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-8_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-8\",\"order\":7,\"canonicalText\":\"「公子尾、公子夏者，景公之二弟也，甚得齊民，家富貴而民說之，擬於公室，此危吾位者也，今謂我惠民者，使我與二弟爭民邪？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-8_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-8\",\"order\":8,\"canonicalText\":\"」於是反國發廩粟以賦眾貧，散府餘財以賜孤寡，倉無陳粟，府無餘財，宮婦不御者出嫁之，七十受祿米，鬻德惠施於民也，已與二弟爭。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-8_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-8\",\"order\":9,\"canonicalText\":\"居二年，二弟出走，公子夏逃楚，公子尾走晉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":1,\"canonicalText\":\"景公與晏子游於少海，登柏寢之臺而還望其國，曰：「美哉，泱泱乎，堂堂乎，後世將孰有此？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":2,\"canonicalText\":\"」晏子對曰：「其田成氏乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":3,\"canonicalText\":\"」景公曰：「寡人有此國也，而曰田成氏有之，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":4,\"canonicalText\":\"」晏子對曰：「夫田成氏甚得齊民，其於民也，上之請爵祿行諸大臣，下之私大斗斛區釜以出貸，小鬥斛區釜以收之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":5,\"canonicalText\":\"殺一牛，取一豆肉，餘以食士。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":6,\"canonicalText\":\"終歲，布帛取二制焉，餘以衣士。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":7,\"canonicalText\":\"故市木之價不加貴於山，澤之魚鹽龜鱉蠃蚌不加貴於海。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":8,\"canonicalText\":\"君重斂，而田成氏厚施。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":9,\"canonicalText\":\"齊嘗大飢，道旁餓死者不可勝數也，父子相牽而趨田成氏者不聞不生。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":10,\"canonicalText\":\"故周秦之民相與歌之曰：謳乎，其己乎苞乎，其往歸田成子乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":11,\"canonicalText\":\"《詩》曰：『雖無德與女，式歌且舞。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":12,\"canonicalText\":\"』今田成氏之德，而民之歌舞，民德歸之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":13,\"canonicalText\":\"故曰：其田成氏乎。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":14,\"canonicalText\":\"」公泫然出涕曰：「不亦悲乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":15,\"canonicalText\":\"寡人有國而田成氏有之，今為之奈何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":16,\"canonicalText\":\"」晏子對曰：「君何患焉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":17,\"canonicalText\":\"若君欲奪之，則近賢而遠不肖，治其煩亂，緩其刑罰，振貧窮而恤孤寡，行恩惠而給不足，民將歸君，則雖有十田成氏，其如君何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-9_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-9\",\"order\":18,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-10_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-10\",\"order\":1,\"canonicalText\":\"或曰：景公不知用勢，而師曠、晏子不知除患。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-10_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-10\",\"order\":2,\"canonicalText\":\"夫獵者，託車輿之安，用六馬之足，使王良佐轡，則身不勞而易及輕獸矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-10_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-10\",\"order\":3,\"canonicalText\":\"今釋車輿之利，捐六馬之足與王良之御，而下走逐獸，則雖樓季之足無時及獸矣，託良馬固車則臧獲有餘。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-10_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-10\",\"order\":4,\"canonicalText\":\"國者、君之車也，勢者、君之馬也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-10_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-10\",\"order\":5,\"canonicalText\":\"夫不處勢以禁誅擅愛之臣，而必德厚以與天下齊行以爭民，是皆不乘君之車，不因馬之利車而下走者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-10_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-10\",\"order\":6,\"canonicalText\":\"故曰：景公不知用勢之主也，而師曠、晏子不知除患之臣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-11_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-11\",\"order\":1,\"canonicalText\":\"子夏曰：「春秋之記臣殺君，子殺父者，以十數矣，皆非一日之積也，有漸而以至矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-11_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-11\",\"order\":2,\"canonicalText\":\"」凡姦者，行久而成積，積成而力多，力多而能殺，故明主蚤絕之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-11_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-11\",\"order\":3,\"canonicalText\":\"今田常之為亂，有漸見矣，而君不誅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-11_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-11\",\"order\":4,\"canonicalText\":\"晏子不使其君禁侵陵之臣，而使其主行惠，故簡公受其禍。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-11_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-11\",\"order\":5,\"canonicalText\":\"故子夏曰：「善持勢者蚤絕姦之萌。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-11_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-11\",\"order\":6,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":1,\"canonicalText\":\"季孫相魯，子路為郈令。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":2,\"canonicalText\":\"魯以五月起眾為長溝，當此之為，子路以其私秩粟為漿飯，要作溝者於五父之衢而餐之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":3,\"canonicalText\":\"孔子聞之，使子貢往覆其飯，擊毀其器，曰：「魯君有民，子奚為乃餐之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":4,\"canonicalText\":\"」子路怫然怒，攘肱而入請曰：「夫子疾由之為仁義乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":5,\"canonicalText\":\"所學於夫子者仁義也，仁義者，與天下共其所有而同其利者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":6,\"canonicalText\":\"今以由之秩粟而餐民，不可何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":7,\"canonicalText\":\"」孔子曰：「由之野也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":8,\"canonicalText\":\"吾以女知之，女徒未及也，女故如是之不知禮也！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":9,\"canonicalText\":\"女之餐之，為愛之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":10,\"canonicalText\":\"夫禮，天子愛天下，諸侯愛境內，大夫愛官職，士愛其家，過其所愛曰侵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":11,\"canonicalText\":\"今魯君有民而子擅愛之，是子侵也，不亦誣乎！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":12,\"canonicalText\":\"」言未卒，而季孫使者至，讓曰：「肥也起民而使之，先生使弟子令徒役而餐之，將奪肥之民耶？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":13,\"canonicalText\":\"」孔子駕而去魯。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":14,\"canonicalText\":\"以孔子之賢，而季孫非魯君也，以人臣之資，假人主之術，蚤禁於未形，而子路不得行其私惠，而害不得生，況人主乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-12_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-12\",\"order\":15,\"canonicalText\":\"以景公之勢而禁田常之侵也，則必無劫弒之患矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":1,\"canonicalText\":\"太公望東封於齊，齊東海上有居士曰狂矞、華士，昆弟二人者立議曰：「吾不臣天子，不友諸侯，耕作而食之，掘井而飲之，吾無求於人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":2,\"canonicalText\":\"無上之名，無君之祿，不事仕而事力。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":3,\"canonicalText\":\"」太公望至於營丘，使吏執殺之以為首誅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":4,\"canonicalText\":\"周公旦從魯聞之，發急傳而問之曰：「夫二子，賢者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":5,\"canonicalText\":\"今日饗國而殺賢者，何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":6,\"canonicalText\":\"」太公望曰：「是昆弟二人立議曰：『吾不臣天子，不友諸侯，耕作而食之，掘井而飲之，吾無求於人也，無上之名，無君之祿，不事仕而事力。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":7,\"canonicalText\":\"』彼不臣天子者，是望不得而臣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":8,\"canonicalText\":\"不友諸侯者，是望不得而使也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":9,\"canonicalText\":\"耕作而食之，掘井而飲之，無求於人者，是望不得以賞罰勸禁也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":10,\"canonicalText\":\"且無上名，雖知、不為望用；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":11,\"canonicalText\":\"不仰君祿，雖賢、不為望功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":12,\"canonicalText\":\"不仕則不治，不任則不忠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":13,\"canonicalText\":\"且先王之所以使其臣民者，非爵祿則刑罰也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":14,\"canonicalText\":\"今四者不足以使之，則望當誰為君乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":15,\"canonicalText\":\"不服兵革而顯，不親耕耨而名，又所以教於國也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":16,\"canonicalText\":\"今有馬於此，如驥之狀者，天下之至良也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":17,\"canonicalText\":\"然而驅之不前，卻之不止，左之不左，右之不右，則臧獲雖賤，不託其足。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":18,\"canonicalText\":\"臧獲之所願託其足於驥者，以驥之可以追利闢害也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":19,\"canonicalText\":\"今不為人用，臧獲雖賤，不託其足焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-20\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":20,\"canonicalText\":\"已自謂以為世之賢士，而不為主用，行極賢而不用於君，此非明主之所臣也，亦驥之不可左右矣，是以誅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-13_s-21\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-13\",\"order\":21,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-14_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-14\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-14_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-14\",\"order\":2,\"canonicalText\":\"太公望東封於齊，海上有賢者狂矞，太公望聞之往請焉，三卻馬於門而狂矞不報見也，太公望誅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-14_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-14\",\"order\":3,\"canonicalText\":\"當是時也，周公旦在魯，馳往止之，比至，已誅之矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-14_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-14\",\"order\":4,\"canonicalText\":\"周公旦曰：「狂矞，天下賢者也，夫子何為誅之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-14_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-14\",\"order\":5,\"canonicalText\":\"」太公望曰：「狂矞也議不臣天子，不友諸侯，吾恐其亂法易教也，故以為首誅。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-14_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-14\",\"order\":6,\"canonicalText\":\"今有馬於此，形容似驥也，然驅之不往，引之不前，雖臧獲不託足以旋其軫也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-14_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-14\",\"order\":7,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-15_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-15\",\"order\":1,\"canonicalText\":\"如耳說衛嗣公，衛嗣公說而太息。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-15_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-15\",\"order\":2,\"canonicalText\":\"左右曰：「公何為不相也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-15_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-15\",\"order\":3,\"canonicalText\":\"」公曰：「夫馬似鹿者而題之千金，然而有百金之馬而無一金之鹿者，馬為人用而鹿不為人用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-15_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-15\",\"order\":4,\"canonicalText\":\"今如耳，萬乘之相也，外有大國之意，其心不在衛，雖辯智，亦不為寡人用，吾是以不相也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-15_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-15\",\"order\":5,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":1,\"canonicalText\":\"薛公之相魏昭侯也，左右有欒子者曰陽胡、潘，其於王甚重，而不為薛公，薛公患之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":2,\"canonicalText\":\"於是乃召與之博，予之人百金，令之昆弟博，俄又益之人二百金。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":3,\"canonicalText\":\"方博有閒，謁者言客張季之子在門，公怫然怒，撫兵而授謁者曰：「殺之，吾聞季之不為文也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":4,\"canonicalText\":\"」立有閒，時季羽在側，曰：「不然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":5,\"canonicalText\":\"竊聞季為公甚，顧其人陰未聞耳。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":6,\"canonicalText\":\"」乃輟不殺客，而大禮之曰：「曩者聞季之不為文也，故欲殺之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":7,\"canonicalText\":\"今誠為文也，豈忘季哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":8,\"canonicalText\":\"」告廩獻千石之粟，告府獻五百金，告騶私廄獻良馬固車二乘，因令奄將宮人之美妾二十人並遺季也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":9,\"canonicalText\":\"欒子因相謂曰：「為公者必利，不為公者必害，吾曹何愛不為公？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":10,\"canonicalText\":\"」因私競勸而遂為之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":11,\"canonicalText\":\"薛公以人臣之勢，假人主之術也，而害不得生，況錯之人主乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":12,\"canonicalText\":\"夫馴烏者斷其下翎焉，斷其下翎則必恃人而食，焉得不馴乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":13,\"canonicalText\":\"夫明主畜臣亦然，令臣不得不利君之祿，不得無服上之名；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-16_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-16\",\"order\":14,\"canonicalText\":\"夫利君之祿，服上之名，焉得不服？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-17_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-17\",\"order\":1,\"canonicalText\":\"說二\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-18_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-18\",\"order\":1,\"canonicalText\":\"《申子》曰：「上明見，人備之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-18_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-18\",\"order\":2,\"canonicalText\":\"其不明見，人惑之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-18_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-18\",\"order\":3,\"canonicalText\":\"其知見，人惑之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-18_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-18\",\"order\":4,\"canonicalText\":\"不知見，人匿之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-18_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-18\",\"order\":5,\"canonicalText\":\"其無欲見，人司之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-18_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-18\",\"order\":6,\"canonicalText\":\"其有欲見，人餌之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-18_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-18\",\"order\":7,\"canonicalText\":\"故曰：吾無從知之，惟無為可以規之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-18_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-18\",\"order\":8,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-19_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-19\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-19_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-19\",\"order\":2,\"canonicalText\":\"《申子》曰：「慎而言也，人且知女；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-19_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-19\",\"order\":3,\"canonicalText\":\"慎而行也，人且隨女。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-19_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-19\",\"order\":4,\"canonicalText\":\"而有知見也，人且匿女；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-19_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-19\",\"order\":5,\"canonicalText\":\"而無知見也，人且意女。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-19_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-19\",\"order\":6,\"canonicalText\":\"女有知也，人且臧女；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-19_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-19\",\"order\":7,\"canonicalText\":\"女無知也，人且行女。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-19_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-19\",\"order\":8,\"canonicalText\":\"故曰：惟無為可以規之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-19_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-19\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-20_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-20\",\"order\":1,\"canonicalText\":\"田子方問唐易鞠曰：「弋者何慎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-20_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-20\",\"order\":2,\"canonicalText\":\"」對曰：「鳥以數百目視子，子以二目御之，子謹周子廩。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-20_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-20\",\"order\":3,\"canonicalText\":\"」田子方曰：「善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-20_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-20\",\"order\":4,\"canonicalText\":\"子加之弋，我加之國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-20_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-20\",\"order\":5,\"canonicalText\":\"」鄭長者聞之曰：「田子方知欲為廩，而未得所以為廩。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-20_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-20\",\"order\":6,\"canonicalText\":\"夫虛無無見者廩也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-20_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-20\",\"order\":7,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":2,\"canonicalText\":\"齊宣王問弋於唐易子曰：「弋者奚貴？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":3,\"canonicalText\":\"」唐易子曰：「在於謹廩。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":4,\"canonicalText\":\"」王曰：「何謂謹廩？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":5,\"canonicalText\":\"」對曰：「鳥以數十目視人，人以二目視鳥，奈何不謹廩也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":6,\"canonicalText\":\"故曰在於謹廩也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":7,\"canonicalText\":\"」王曰：「然則為天下何以為此廩？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":8,\"canonicalText\":\"今人主以二目視一國，一國以萬目視人主，將何以自為廩乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":9,\"canonicalText\":\"」對曰：「鄭長者有言曰：『夫虛靜無為而無見也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":10,\"canonicalText\":\"』其可以為此廩乎。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-21_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-21\",\"order\":11,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-22_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-22\",\"order\":1,\"canonicalText\":\"國羊重於鄭君，聞君之惡己也，侍飲，因先謂君曰：「臣適不幸而有過，願君幸而告之，臣請變更，則臣免死罪矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-22_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-22\",\"order\":2,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-23_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-23\",\"order\":1,\"canonicalText\":\"客有說韓宣王，宣王說而太息，左右引王之說之以先告客以為德。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-24_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-24\",\"order\":1,\"canonicalText\":\"靖郭君之相齊也，王后死，未知所置，乃獻玉珥以知之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-25_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-25\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-25_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-25\",\"order\":2,\"canonicalText\":\"薛公相齊，齊威王夫人死，中有十孺子皆貴於王，薛公欲知王所欲立而請置一人以為夫人，王聽之、則是說行於王而重於置夫人也，王不聽、是說不行而輕於置夫人也，欲先知王之所欲置以勸王置之，於是為十玉珥而美其一而獻之，王以賦十孺子，明日坐，視美珥之所在而勸王以為夫人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-26_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-26\",\"order\":1,\"canonicalText\":\"甘茂相秦惠王，惠王愛公孫衍，與之閒有所言，曰：「寡人將相子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-26_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-26\",\"order\":2,\"canonicalText\":\"」甘茂之吏道穴聞之，以告甘茂，甘茂入見王，曰：「王得賢相，臣敢再拜賀。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-26_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-26\",\"order\":3,\"canonicalText\":\"」王曰：「寡人託國於子，安更得賢相？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-26_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-26\",\"order\":4,\"canonicalText\":\"」對曰：「將相犀首。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-26_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-26\",\"order\":5,\"canonicalText\":\"」王曰：「子安聞之？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-26_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-26\",\"order\":6,\"canonicalText\":\"」對曰：「犀首告臣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-26_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-26\",\"order\":7,\"canonicalText\":\"」王怒犀首之泄，乃逐之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":2,\"canonicalText\":\"犀首，天下之善將也，梁王之臣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":3,\"canonicalText\":\"秦王欲得之與治天下，犀首曰：「衍其人臣者也，不敢離主之國。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":4,\"canonicalText\":\"」居期年，犀首抵罪於梁王，逃而入秦，秦王甚善之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":5,\"canonicalText\":\"樗裏疾，秦之將也，恐犀首之代之將也，鑿穴於王之所常隱語者，俄而王果與犀首計曰：「吾欲攻韓，奚如？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":6,\"canonicalText\":\"」犀首曰：「秋可矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":7,\"canonicalText\":\"」王曰：「吾欲以國累子，子必勿泄也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":8,\"canonicalText\":\"」犀首反走再拜曰：「受命。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":9,\"canonicalText\":\"」於是樗裏疾也道穴聽之，矣郎中皆曰：「兵秋起攻韓犀首為將。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":10,\"canonicalText\":\"」於是日也郎中盡知之，於是月也境內盡知之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":11,\"canonicalText\":\"王召樗裏疾曰：「是何匈匈也，何道出？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":12,\"canonicalText\":\"」樗裏疾曰：「似犀首也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":13,\"canonicalText\":\"」王曰：「吾無與犀首言也，其犀首何哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":14,\"canonicalText\":\"」樗裏疾曰：「犀首也羈旅，新抵罪，其心孤，是言自嫁於眾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":15,\"canonicalText\":\"」王曰：「然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-27_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-27\",\"order\":16,\"canonicalText\":\"」使人召犀首，已逃諸侯矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-28_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-28\",\"order\":1,\"canonicalText\":\"堂谿公謂昭侯曰：「今有千金之玉卮，通而無當，可以盛水乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-28_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-28\",\"order\":2,\"canonicalText\":\"」昭侯曰：「不可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-28_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-28\",\"order\":3,\"canonicalText\":\"」「有瓦器而不漏，可以盛酒乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-28_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-28\",\"order\":4,\"canonicalText\":\"」昭侯曰：「可。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-28_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-28\",\"order\":5,\"canonicalText\":\"」對曰：「夫瓦器至賤也，不漏，可以盛酒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-28_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-28\",\"order\":6,\"canonicalText\":\"雖有乎千金之玉卮，至貴，而無當，漏，不可盛水，則人孰注漿哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-28_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-28\",\"order\":7,\"canonicalText\":\"今為人主而漏其群臣之語，是猶無當之玉卮也，雖有聖智，莫盡其術，為其漏也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-28_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-28\",\"order\":8,\"canonicalText\":\"」昭侯曰：「然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-28_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-28\",\"order\":9,\"canonicalText\":\"」昭侯聞堂谿公之言，自此之後，欲發天下之大事，未嘗不獨寢，恐夢言而使人知其謀也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-29_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-29\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-29_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-29\",\"order\":2,\"canonicalText\":\"堂谿公見昭侯曰：「今有白玉之卮而無當，有瓦卮而有當，君渴，將何以飲？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-29_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-29\",\"order\":3,\"canonicalText\":\"」君曰：「以瓦卮。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-29_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-29\",\"order\":4,\"canonicalText\":\"」堂谿公曰：「白玉之卮美，而君不以飲者，以其無當耶？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-29_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-29\",\"order\":5,\"canonicalText\":\"」君曰：「然。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-29_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-29\",\"order\":6,\"canonicalText\":\"」堂谿公曰：「為人主而漏泄其群臣之語，譬猶玉卮之無當。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-29_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-29\",\"order\":7,\"canonicalText\":\"」堂谿公每見而出，昭侯必獨臥，惟恐夢言泄於妻妾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-30_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-30\",\"order\":1,\"canonicalText\":\"《申子》曰：「獨視者謂明，獨聽者謂聰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-30_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-30\",\"order\":2,\"canonicalText\":\"能獨斷者，故可以為天下主。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-30_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-30\",\"order\":3,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-31_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-31\",\"order\":1,\"canonicalText\":\"說三\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":1,\"canonicalText\":\"宋人有酤酒者，升概甚平，遇客甚謹，為酒甚美，縣幟甚高，著然不售，酒酸，怪其故，問其所知閭1長者楊倩，倩曰：「汝狗猛耶。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":2,\"canonicalText\":\"」曰：「狗猛則酒何故而不售？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":3,\"canonicalText\":\"」曰：「人畏焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":4,\"canonicalText\":\"或令孺子懷錢挈壺罋而往酤，而狗迓而齕之，此酒所以酸而不售也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":5,\"canonicalText\":\"」夫國亦有狗，有道之士懷其術而欲以明萬乘之主，大臣為猛狗迎而齕之，此人主之所以蔽脅，而有道之士所以不用也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":6,\"canonicalText\":\"故桓公問管仲「治國最奚患？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":7,\"canonicalText\":\"」對曰：「最患社鼠矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":8,\"canonicalText\":\"」公曰：「何患社鼠哉？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":9,\"canonicalText\":\"」對曰：「君亦見夫為社者乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":10,\"canonicalText\":\"樹木而塗之，鼠穿其間，掘穴託其中，燻之則恐焚木，灌之則恐塗阤，此社鼠之所以不得也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":11,\"canonicalText\":\"今人君之左右，出則為勢重而收利於民，入則比周而蔽惡於君，內閒主之情以告外，外內為重，諸臣百吏以為富，吏不誅則亂法，誅之則君不安，據而有之，此亦國之社鼠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":12,\"canonicalText\":\"」故人臣執柄而擅禁，明為己者必利，而不為己者必害，此亦猛狗也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-32_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-32\",\"order\":13,\"canonicalText\":\"夫大臣為猛狗而齕有道之士矣，左右又為社鼠而閒主之情，人主不覺，如此，主焉得無壅，國焉得無亡乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-33_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-33\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-33_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-33\",\"order\":2,\"canonicalText\":\"宋之酤酒者有莊氏者，其酒常美，或使僕往酤莊氏之酒，其狗齕人，使者不敢往，乃酤佗家之酒，問曰：「何為不酤莊氏之酒？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-33_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-33\",\"order\":3,\"canonicalText\":\"」對曰：「今日莊氏之酒酸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-33_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-33\",\"order\":4,\"canonicalText\":\"」故曰：不殺其狗則酒酸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-34_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-34\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-34_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-34\",\"order\":2,\"canonicalText\":\"桓公問管仲曰：「治國何患？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-34_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-34\",\"order\":3,\"canonicalText\":\"」對曰：「最苦社鼠。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-34_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-34\",\"order\":4,\"canonicalText\":\"夫社木而塗之，鼠因自託也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-34_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-34\",\"order\":5,\"canonicalText\":\"燻之則木焚，灌之則塗阤，此所以苦於社鼠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-34_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-34\",\"order\":6,\"canonicalText\":\"今人君左右，出則為勢重以收利於民，入則比周謾侮蔽惡以欺於君，不誅則亂法，誅之則人主危，據而有之，此亦社鼠也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-34_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-34\",\"order\":7,\"canonicalText\":\"」故人臣執柄擅禁，明為己者必利，不為己者必害，亦猛狗也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-34_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-34\",\"order\":8,\"canonicalText\":\"故左右為社鼠，用事者為猛狗，則術不行矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":1,\"canonicalText\":\"堯欲傳天下於舜，鯀諫曰：「不祥哉！\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":2,\"canonicalText\":\"孰以天下而傳之於匹夫乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":3,\"canonicalText\":\"」堯不聽，舉兵而誅，殺鯀於羽山之郊。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":4,\"canonicalText\":\"共工又諫曰：「孰以天下而傳之於匹夫乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":5,\"canonicalText\":\"」堯不聽，又舉兵而誅，共工於幽州之都。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":6,\"canonicalText\":\"於是天下莫敢言無傳天下於舜。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":7,\"canonicalText\":\"仲尼聞之曰：「堯之知，舜之賢，非其難者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":8,\"canonicalText\":\"夫至乎誅諫者必傳之舜，乃其難也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":9,\"canonicalText\":\"」一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":10,\"canonicalText\":\"「不以其所疑敗其所察則難也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-35_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-35\",\"order\":11,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-36_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-36\",\"order\":1,\"canonicalText\":\"荊莊王有茅門之法曰：「群臣大夫諸公子入朝，馬蹄踐霤者，廷理斬其輈，戮其御。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-36_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-36\",\"order\":2,\"canonicalText\":\"」於是太子入朝，馬蹄踐霤，廷理斬其輈，戮其御。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-36_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-36\",\"order\":3,\"canonicalText\":\"太子怒，入為王泣曰：「為我誅戮廷理。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-36_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-36\",\"order\":4,\"canonicalText\":\"」王曰：「法者所以敬宗廟，尊社稷。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-36_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-36\",\"order\":5,\"canonicalText\":\"故能立法從令尊敬社稷者，社稷之臣也，焉可誅也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-36_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-36\",\"order\":6,\"canonicalText\":\"夫犯法廢令不尊敬社稷者，是臣乘君而下尚校也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-36_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-36\",\"order\":7,\"canonicalText\":\"臣乘君則主失威，下尚校則上位危。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-36_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-36\",\"order\":8,\"canonicalText\":\"威失位危，社稷不守，吾將何以遺子孫？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-36_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-36\",\"order\":9,\"canonicalText\":\"」於是太子乃還走，避舍露宿三日，北面再拜請死罪。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":2,\"canonicalText\":\"楚王急召太子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":3,\"canonicalText\":\"楚國之法，車不得至於茆門。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":4,\"canonicalText\":\"天雨，廷中有潦，太子遂驅車至於茆門。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":5,\"canonicalText\":\"廷理曰：「車不得至茆門，非法也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":6,\"canonicalText\":\"」太子曰：「王召急，不得須無潦。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":7,\"canonicalText\":\"」遂驅之，廷理舉殳而擊其馬，敗其駕。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":8,\"canonicalText\":\"太子入為王泣曰：「廷中多潦，驅車至茆門，廷理曰非法也，舉殳擊臣馬，敗臣駕，王必誅之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":9,\"canonicalText\":\"」王曰：「前有老主而不踰，後有儲主而不屬，矜矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":10,\"canonicalText\":\"是真吾守法之臣也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":11,\"canonicalText\":\"」乃益爵二級，而開後門出太子。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":12,\"canonicalText\":\"「勿復過。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-37_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-37\",\"order\":13,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":1,\"canonicalText\":\"衛嗣君謂薄疑曰：「子小寡人之國以為不足仕，則寡人力能仕子，請進爵以子為上卿。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":2,\"canonicalText\":\"」乃進田萬頃。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":3,\"canonicalText\":\"薄子曰：「疑之母親疑，以疑為能相萬乘所不窕也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":4,\"canonicalText\":\"然疑家巫有蔡嫗者，疑母甚愛信之，屬之家事焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":5,\"canonicalText\":\"疑智足以信言家事，疑母盡以聽疑也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":6,\"canonicalText\":\"然已與疑言者，亦必復決之於蔡嫗也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":7,\"canonicalText\":\"故論疑之智能，以疑為能相萬乘而不窕也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":8,\"canonicalText\":\"論其親，則子母之間也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":9,\"canonicalText\":\"然猶不免議之於蔡嫗也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":10,\"canonicalText\":\"今疑之於人主也，非子母之親也，而人主皆有蔡嫗。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":11,\"canonicalText\":\"人主之蔡嫗，必其重人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":12,\"canonicalText\":\"重人者，能行私者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":13,\"canonicalText\":\"夫行私者，繩之外也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":14,\"canonicalText\":\"而疑之所言，法之內也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":15,\"canonicalText\":\"繩之外與法之內，讎也，不相受也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-38_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-38\",\"order\":16,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":2,\"canonicalText\":\"衛君之晉，謂薄疑曰：「吾欲與子皆行。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":3,\"canonicalText\":\"」薄疑曰：「媼也在中，請歸與媼計之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":4,\"canonicalText\":\"衛君自請薄媼，薄媼曰：「疑，君之臣也，君有意從之，甚善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":5,\"canonicalText\":\"」衛君曰：「吾以請之媼，媼許我矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":6,\"canonicalText\":\"」薄疑歸言之媼也，曰：「衛君之愛疑奚與媼？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":7,\"canonicalText\":\"」媼曰：「不如吾愛子也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":8,\"canonicalText\":\"」「衛君之賢疑奚與媼也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":9,\"canonicalText\":\"」曰：「不如吾賢子也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":10,\"canonicalText\":\"」「媼與疑計家事，已決矣，乃請決之於卜者蔡嫗。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":11,\"canonicalText\":\"今衛君從疑而行，雖與疑決計，必與他蔡嫗敗之，如是則疑不得長為臣矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-39_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-39\",\"order\":12,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-40_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-40\",\"order\":1,\"canonicalText\":\"夫教歌者，使先呼而詘之，其聲反清徵者乃教之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-41_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-41\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-41_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-41\",\"order\":2,\"canonicalText\":\"教歌者，先揆以法，疾呼中宮，徐呼中徵。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-41_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-41\",\"order\":3,\"canonicalText\":\"疾不中宮，徐不中徵，不可謂教。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-42_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-42\",\"order\":1,\"canonicalText\":\"吳起，衛左氏中人也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-42_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-42\",\"order\":2,\"canonicalText\":\"使其妻織組而幅狹於度，吳子使更之，其妻曰：「諾。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-42_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-42\",\"order\":3,\"canonicalText\":\"」及成，復度之，果不中度，吳子大怒。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-42_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-42\",\"order\":4,\"canonicalText\":\"其妻對曰：「吾始經之而不可更也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-42_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-42\",\"order\":5,\"canonicalText\":\"」吳子出之，其妻請其兄而索入，其兄曰：「吳子，為法者也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-42_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-42\",\"order\":6,\"canonicalText\":\"其為法也，且欲以與萬乘致功，必先踐之妻妾然後行之，子毋幾索入矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-42_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-42\",\"order\":7,\"canonicalText\":\"」其妻之弟又重於衛君，乃因以衛君之重請吳子，吳子不聽，遂去衛而入荊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-43_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-43\",\"order\":1,\"canonicalText\":\"一曰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-43_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-43\",\"order\":2,\"canonicalText\":\"吳起示其妻以組曰：「子為我織組，令之如是。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-43_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-43\",\"order\":3,\"canonicalText\":\"」組已就而效之，其組異善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-43_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-43\",\"order\":4,\"canonicalText\":\"起曰：「使子為組，令之如是，而今也異善何也？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-43_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-43\",\"order\":5,\"canonicalText\":\"」其妻曰：「用財若一也，加務善之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-43_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-43\",\"order\":6,\"canonicalText\":\"」吳起曰：「非語也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-43_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-43\",\"order\":7,\"canonicalText\":\"」使之衣歸。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-43_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-43\",\"order\":8,\"canonicalText\":\"其父往請之，吳起曰：「起家無虛言。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-43_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-43\",\"order\":9,\"canonicalText\":\"」\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":1,\"canonicalText\":\"晉文公問於狐偃曰：「寡人甘肥周於堂，卮酒豆肉集於宮，壺酒不清，生肉不布，殺一牛遍於國中，一歲之功盡以衣士卒，其足以戰民乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":2,\"canonicalText\":\"」狐子曰：「不足。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":3,\"canonicalText\":\"」文公曰：「吾弛關市之徵而緩刑罰，其足以戰民乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":4,\"canonicalText\":\"」狐子曰：「不足。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":5,\"canonicalText\":\"」文公曰：「吾民之有喪資者，寡人親使郎中視事；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":6,\"canonicalText\":\"有罪者赦之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":7,\"canonicalText\":\"貧窮不足者與之；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":8,\"canonicalText\":\"其足以戰民乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-9\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":9,\"canonicalText\":\"」狐子對曰：「不足。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-10\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":10,\"canonicalText\":\"此皆所以慎產也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-11\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":11,\"canonicalText\":\"而戰之者，殺之也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-12\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":12,\"canonicalText\":\"民之從公也，為慎產也，公因而迎殺之，失所以為從公矣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-13\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":13,\"canonicalText\":\"」曰：「然則何如足以戰民乎？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-14\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":14,\"canonicalText\":\"」狐子對曰：「令無得不戰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-15\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":15,\"canonicalText\":\"」公曰：「無得不戰奈何？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-16\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":16,\"canonicalText\":\"」狐子對曰：「信賞必罰，其足以戰。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-17\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":17,\"canonicalText\":\"」公曰：「刑罰之極安至？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-18\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":18,\"canonicalText\":\"」對曰：「不闢親貴，法行所愛。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-19\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":19,\"canonicalText\":\"」文公曰：「善。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-20\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":20,\"canonicalText\":\"」明日令田於圃陸，期以日中為期，後期者行軍法焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-21\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":21,\"canonicalText\":\"於是公有所愛者曰顛頡後期，吏請其罪，文公隕涕而憂。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-22\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":22,\"canonicalText\":\"吏曰：「請用事焉。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-23\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":23,\"canonicalText\":\"」遂斬顛頡之脊，以徇百姓，以明法之信也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-24\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":24,\"canonicalText\":\"而後百姓皆懼曰：「君於顛頡之貴重如彼甚也，而君猶行法焉，況於我則何有矣？\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-25\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":25,\"canonicalText\":\"」文公見民之可戰也，於是遂興兵伐原，克之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-26\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":26,\"canonicalText\":\"伐衛，東其畝，取五鹿。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-27\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":27,\"canonicalText\":\"攻陽，勝虢，伐曹。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-28\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":28,\"canonicalText\":\"南圍鄭，反之陴。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-29\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":29,\"canonicalText\":\"罷宋圍，還與荊人戰城濮，大敗荊人，返為踐土之盟，遂成衡雍之義。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-30\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":30,\"canonicalText\":\"一舉而八有功。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-44_s-31\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-44\",\"order\":31,\"canonicalText\":\"所以然者，無他故異物，從狐偃之謀，假顛頡之脊也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-45_s-1\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-45\",\"order\":1,\"canonicalText\":\"夫痤疽之痛也，非刺骨髓，則煩心不可支也；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-45_s-2\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-45\",\"order\":2,\"canonicalText\":\"非如是不能使人以半寸砥石彈之。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-45_s-3\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-45\",\"order\":3,\"canonicalText\":\"今人主之於治亦然，非不知有苦則安；\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-45_s-4\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-45\",\"order\":4,\"canonicalText\":\"欲治其國，非如是不能聽聖知而誅亂臣。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-45_s-5\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-45\",\"order\":5,\"canonicalText\":\"亂臣者，必重人。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-45_s-6\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-45\",\"order\":6,\"canonicalText\":\"重人者，必人主所甚親愛也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-45_s-7\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-45\",\"order\":7,\"canonicalText\":\"人主所甚親愛也者，是同堅白也。\",\"chunks\":[],\"tags\":[]},{\"id\":\"han-fei-zi_ch-34_p-45_s-8\",\"workId\":\"han-fei-zi\",\"chapterId\":\"han-fei-zi_ch-34\",\"passageId\":\"han-fei-zi_ch-34_p-45\",\"order\":8,\"canonicalText\":\"夫以布衣之資，欲以離人主之堅白、所愛，是以解左髀說右髀者，是身必死而說不行者也。\",\"chunks\":[],\"tags\":[]}]}") as ChapterBundle
